UPDATE equipment SET name_ja = 'グレイスショテル', description_ja = 'レイギエナの太刀。 研ぎ澄まされた冷やかな切っ先は、美しい流線型を描く。', name_fr = 'Shotel polaire', description_fr = 'Épée longue Legiana. Sa lame de glace forme d''élégantes arabesques.', name_it = 'Shotel glaciale', description_it = 'Algida e affilata spada lunga di Legiana che colpisce con leggiadria ed eleganza.', name_es = 'Shotel Glacial', description_es = 'Gélida espada larga de Legiana refinada que zumba mientras dibuja arcos y figuras.' WHERE name_en = 'Glacial Shotel' AND type = 'longsword';
UPDATE equipment SET name_ja = '飛竜刀【翠】', description_ja = '雌火竜の素材を用いて作られた深緑の飛竜刀。 高い鋭さと、威力を両立した業物である。', name_fr = 'Lame wyverne "Verte"', description_fr = 'Lame vert sombre à base de matériaux de Rathian. Incroyablement tranchante et puissante.', name_it = 'Lama wyvern Verde', description_it = 'Lama verde scuro fatta con materiale di Rathian. Molto affilata e potente.', name_es = 'Hoja wyvern "Verde"', description_es = 'Hoja verde oscura de material de Rathian. Muy afilada y potente.' WHERE name_en = 'Wyvern Blade "Verde"' AND type = 'longsword';
UPDATE equipment SET name_ja = 'クルーエルペイン', description_ja = '恐暴竜の骨と肉で作られた生きた巨刀。 抜刀と共に姿を見せる刃が無慈悲に獲物を切り刻む。', name_fr = 'Saccageur "Cruauté"', description_fr = 'Lame vivante faite en viande et en os de Deviljho, ayant un sacré mordant.', name_it = 'Crudeltà straziante', description_it = 'Lama viva creata con carne e ossa di Deviljho e dotata di un morso spietato.', name_es = 'Cólera "Crueldad"', description_es = 'Espada viviente hecha de carne y hueso de Deviljho; su embate es implacable.' WHERE name_en = 'Reaver "Cruelty"' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ヒドゥンサーベル', description_ja = '夜陰に紛れる暗黒の太刀。 月に照らされた刀影を見れば最期、生きては帰れない。', name_fr = 'Sabre occulte', description_fr = 'Épée longue empreinte de ténèbres. Apercevoir le reflet de la lune dans sa lame est synonyme d''une mort certaine.', name_it = 'Sciabola occulta', description_it = 'Spada lunga impregnata di oscurità. A coloro che intravedono la luce della luna riflessa su questa lama non resta molto da vivere.', name_es = 'Sable oculto', description_es = 'Espada larga bañada en oscuridad. Aquellos que presencian el reflejo de la luna en su hoja están destinados a abandonar pronto este mundo.' WHERE name_en = 'Hidden Saber' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ヒドラ・トルナリア', description_ja = 'ネロミェールの太刀。表裏に闇と光を宿す一本。 明滅する刃は凶兆を従え闇より襲いかかる。', name_fr = 'Tornaria hydra', description_fr = 'Épée longue Namielle. La lumière et les ténèbres coexistent en elle.', name_it = 'Tornaria di Idra', description_it = 'Luce e oscurità coesistono in questa spada lunga di Namielle, che brilla come un triste presagio.', name_es = 'Tornaria Hidra', description_es = 'Luz y oscuridad coexisten en esta espada larga de Namielle. Su brillo advierte a sus enemigos.' WHERE name_en = 'Hydra Tornaria' AND type = 'longsword';
UPDATE equipment SET name_ja = '鉄刀', description_ja = '東方伝来の加工技術の剣。 丹念に加工された刃は強靭で、粘りがある。手入れは重要。', name_fr = 'Katana de fer', description_fr = 'Épée de style oriental. Résistante, mais requiert un entretien régulier.', name_it = 'Katana di ferro', description_it = 'Spada lunga forgiata con tecniche di provenienza orientale. È resistente, ma richiede una buona manutenzione.', name_es = 'Katana de hierro', description_es = 'Espada forjada según una ancestral técnica oriental. Duradera, si la cuidas.' WHERE name_en = 'Iron Katana' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ダイトウ【烏】', description_ja = '強さゆえに孤独となった剣士。 だが真の孤独を知るは、主を失った後の刀のみとも伝わる。', name_fr = 'Daito corbeau', description_fr = 'Seule une lame qui a perdu son porteur connaît la véritable solitude.', name_it = 'Daito corvo', description_it = 'Solo una lama che ha perso il suo proprietario conosce la vera solitudine.', name_es = 'Cuervo Daito', description_es = 'La soledad de un espadachín nunca igualará a la de una espada huérfana de amo.' WHERE name_en = 'Daito Crow' AND type = 'longsword';
UPDATE equipment SET name_ja = '飛雷刀キリカガチ', description_ja = '飛雷竜の鱗から造られた太刀。 その一振りはまさに雷光一閃、獲物は直ちに地へ伏すだろう。', name_fr = 'Étincelle tranchante', description_fr = 'Épée longue en écailles de Tobi-Kadachi. Ses coups sont de puissants éclairs.', name_it = 'Spada Kadachi', description_it = 'Spada ricavata da scaglie di Tobi-Kadachi. Ogni fendente è un lampo potentissimo.', name_es = 'Rebanarrayos', description_es = 'Espada de escamas de Tobi-Kadachi. Cada golpe es como el fulgor de un rayo.' WHERE name_en = 'Spark Slicer' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ディオスソード', description_ja = '砕竜の闘気をその手に感じられる太刀。 輝く刀身は甲殻を貫き内側から爆砕する。', name_fr = 'Katana Dios', description_fr = 'Personnification de l''esprit de combat du Brachydios. Perce et explose les proies.', name_it = 'Katana Dios', description_it = 'Spada lunga con lo spirito del Brachydios. Perfora i nemici e li fa esplodere.', name_es = 'Katana Brach', description_es = 'Espada larga con el arrojo de un Brachydios. Penetra en la víctima y explota en su interior.' WHERE name_en = 'Dios Katana' AND type = 'longsword';
UPDATE equipment SET name_ja = '風ノ賊刀', description_ja = '鎌鼬竜の尾で拵えた刀。 扱いやすい細身の刀身は、山野を駆け巡るのに長けている。', name_fr = 'Cimeterre vole-vent', description_fr = 'Épée longue en queue d''Izuchi. Lame fine polyvalente, facile à utiliser.', name_it = 'Scimitarra rubavento', description_it = 'Ricavata dalla coda di un Izuchi, è una spada versatile e di facile utilizzo.', name_es = 'Cimitarra ladrona viento', description_es = 'Espada de cola de Izuchi, fácil de blandir y con una hoja delgada muy versátil.' WHERE name_en = 'Wind Thief Scimitar' AND type = 'longsword';
UPDATE equipment SET name_ja = 'シルムズサーブル', description_ja = '高熱を帯びた刀身が赤く輝く傘鳥の刀。 折り重ねられたような装飾が繊細で美しい。', name_fr = 'Sabre Aknosom', description_fr = 'Magnifique épée en Aknosom. Émet une lueur rouge à la chaleur intense.', name_it = 'Sciabola Aknosom', description_it = 'Spada di parti di Aknosom. Riccamente decorata, emette un intenso bagliore rosso.', name_es = 'Sable Aknosom', description_es = 'Espada de restos de Aknosom y espléndida ornamentación. Emite un vivo fulgor rojo.' WHERE name_en = 'Aknosom Sabre' AND type = 'longsword';
UPDATE equipment SET name_ja = 'メロウパウ', description_ja = '人魚竜の変種の太刀。複数の刀身から繰り出される 無慈悲な斬撃で、肉はズタズタに…。', name_fr = 'Lame à volants', description_fr = 'Épée longue en Somnacanth. Ses multiples lames font de la chair à pâté des ennemis.', name_it = 'Fendente crestato', description_it = 'Spada di parti di Somnacanth con molteplici lame per fare a pezzi gli avversari.', name_es = 'Tajo crestado', description_es = 'Espada hecha con restos de Somnacanth. Su miríada de hojas hace picadillo a los enemigos.' WHERE name_en = 'Frilled Slash' AND type = 'longsword';
UPDATE equipment SET name_ja = '禍ツ太刀【封】', description_ja = '刀身の禍々しい紋様は怨虎竜が秘める狂怒の顕れ。 その衝動は爆撃となって標的を圧倒する。', name_fr = 'Épée longue sinistre', description_fr = 'Incarnation de la fureur du Magnamalo. Une épée longue redoutable.', name_it = 'Spada lunga sinistra', description_it = 'Spada che incarna la furia del Magnamalo e sovrasta il nemico con facilità.', name_es = 'Filo siniestro', description_es = 'Espada que encarna la furia de Magnamalo y que abruma a su presa con facilidad.' WHERE name_en = 'Sinister Long Sword' AND type = 'longsword';
UPDATE equipment SET name_ja = 'Ｄ＝トゥ', description_ja = '泥翁竜の硬い鱗を用いた太刀。 内部を金の泥が流れているため抜刀時には眩い光を放つ。', name_fr = 'Lame Almudron', description_fr = 'Épée en écailles d''Almudron. La boue dorée qu''elle contient lui donne du cachet.', name_it = 'Lama Almudron', description_it = 'Spada fatta di scaglie di Almudron e fango dorato dall''incantevole luccichio.', name_es = 'Espada Almudron', description_es = 'Espada hecha de escamas de Almudron. El lodo dorado en su interior le confiere un brillo ilustre.' WHERE name_en = 'Almudron Blade' AND type = 'longsword';
UPDATE equipment SET name_ja = 'あかしまの神刀', description_ja = '風巻の龍より出でたる蒼刀は、風を束ねて凪を飲みこみ 凄風を生む。新たな風を待ちながら。', name_fr = 'Épée longue ancienne azur', description_fr = 'Tout comme l''Ibushi du vent, cette épée longue peut invoquer le pouvoir du vent.', name_it = 'Katana dell''anziano celeste', description_it = 'Come l''Ibushi del vento, questa spada può invocare il potere dell''aria.', name_es = 'Espada anciana añil', description_es = 'Espada que domina el poder del viento como lo haría el mismísimo Ibushi.' WHERE name_en = 'Azure Elder Long Sword' AND type = 'longsword';
UPDATE equipment SET name_ja = 'デスペレイション', description_ja = '絶望の象徴とされる鳥を模した鎌。 絶叫をあげるが如く開いた口は、対象の生気を飲み干す。', name_fr = 'Faux du corbeau', description_fr = 'Inlassablement, cette arme délivre son message de mort au fil de ses rencontres.', name_it = 'Falce corvo', description_it = 'Inquietante spada lunga che invia un messaggio di morte attraverso le lande.', name_es = 'Hoja de corneja', description_es = 'Inquietante espada larga que reparte por el mundo un mensaje de muerte.' WHERE name_en = 'Cawscythe' AND type = 'longsword';
UPDATE equipment SET name_ja = '青熊薙', description_ja = '鉱石を鍛えた刃に青熊獣の甲殻を取り合わせた剛強な一振り。 力自慢の猛者たちが愛用する。', name_fr = 'Naginata Arzuros', description_fr = 'Épée longue faite de plaque d''Arzuros et de minerai. Prisée des barbares.', name_it = 'Naginata Arzuros', description_it = 'Spada lunga di piastre di Arzuros e minerali, scelta dai barbari più brutali.', name_es = 'Naginata de Arzuros', description_es = 'Espada larga que aúna placas de Arzuros y mineral. Usada por fuertes bárbaros.' WHERE name_en = 'Arzuros Naginata' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ドラウンポール', description_ja = '水獣の海綿素材を用いた太刀。 飛沫を上げるその攻めは、獲物を地上で溺れ果てさせる。', name_fr = 'Noyeuse', description_fr = 'Longue épée faite à partir de matériaux spongieux de Ludroth royal. Peut noyer n''importe quel ennemi.', name_it = 'Spada dell''annegato', description_it = 'Spada lunga con le parti spugnose di Ludroth reale. Può annegare ogni nemico anche sulla terra.', name_es = 'Fuste de ahogo', description_es = 'Espada larga hecha de materiales esponjosos de Ludroth Real. Sus golpes acuosos ahogan a enemigos.' WHERE name_en = 'Drowning Shaft' AND type = 'longsword';
UPDATE equipment SET name_ja = '狐刀カカルクモナキ', description_ja = '軍神と謳われた士が遺した雅なる刀。 有明の如き麗しさをたたえた刃が阻む者を斬る。', name_fr = 'Kakaru Kumo Naki', description_fr = 'Katana d''un samouraï héros de guerre. Incarne la beauté et la mort.', name_it = 'Kakaru Kumo Naki', description_it = 'Katana di un eroe di guerra samurai. Splendida e letale in egual misura.', name_es = 'Kakaru Kumo Naki', description_es = 'Katana de un héroe de guerra samurái. Bella y letal a partes iguales.' WHERE name_en = 'Kakaru Kumo Naki' AND type = 'longsword';
UPDATE equipment SET name_ja = '王刀ライキリ', description_ja = '荒ぶる王者の具現。この世に神がいるならば、 それさえも斬り捨てると言われる剛の太刀。', name_fr = 'Violence royale', description_fr = 'Épée longue des rois barbares. Si les dieux existent, cette lame doit les effrayer.', name_it = 'Rasoio del tiranno', description_it = 'Spada per re selvaggi. Abbatterebbe anche una divinità.', name_es = 'Cortarrayos usurpador', description_es = 'Espada para reyes feroces, capaz de cortar en dos a los mismísimos dioses.' WHERE name_en = 'Usurper''s Boltslicer' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ショウグンカッター', description_ja = '鎌蟹の素材で作られた太刀。 通常時に収納されている鎌は、いざという時に刃を覗かせる。', name_fr = 'Faux Shogun', description_fr = 'Faux de Ceanataur Shogun. Un bel atout à abattre à l''improviste.', name_it = 'Taglia-Shogun', description_it = 'Falce ricavata da parti di Shogun Ceanataur. Un vero asso nella manica.', name_es = 'Cortador Shogun', description_es = 'Guadaña hecha con partes de Shogun Ceanataur. Constituye una baza poderosa.' WHERE name_en = 'Shogun Cutter' AND type = 'longsword';
UPDATE equipment SET name_ja = 'シミターアルナジト', description_ja = '千刃竜の刃を重ねた太刀。 輝く金の刃は、何度研磨しても決して失われることは無い。', name_fr = 'Lame Khanga', description_fr = 'En écailles de Seregios, son éclat doré résistera à d''innombrables polissages.', name_it = 'Lama Khanga', description_it = 'Fatta di lame di Seregios, la sua dorata lucentezza non svanisce mai.', name_es = 'Hoja Khanga', description_es = 'Esta arma de Seregios hace gala de un brillo dorado que jamás perderá su lustre.' WHERE name_en = 'Khanga Edge' AND type = 'longsword';
UPDATE equipment SET name_ja = '飛竜刀【ベリル】', description_ja = '碧玉の色に染まる飛竜刀。 冷徹さを醸す刃は一太刀ごとに鮮烈たる電撃の洗礼を見舞う。', name_fr = 'Lame wyverne "Béryl"', description_fr = 'Épée de wyverne volante jaspe dont chaque coup plonge ses proies dans un torrent d''électricité.', name_it = 'Saetta wyvern', description_it = 'Ogni colpo di questa spada di wyvern volante color giada è per i mostri un vero e proprio bagno di elettricità.', name_es = 'Rayo de wyvern', description_es = 'Con cada golpe de esta espada de wyvern volador del color del jaspe verde, los monstruos reciben un baño de descargas eléctricas.' WHERE name_en = 'Wyvern Blade "Beryl"' AND type = 'longsword';
UPDATE equipment SET name_ja = 'デュークシンクレア', description_ja = '血塗られた過去を持つ太刀。 かつて多くの者が、その凶刃の犠牲になったという。', name_fr = 'Hécatombe du Duc', description_fr = 'Lame au passé sanglant. Ses victimes se comptent par milliers.', name_it = 'Monda del duca', description_it = 'Il suo passato è costellato di spargimenti di sangue e legioni di vittime.', name_es = 'Sinclair ducal', description_es = 'Espada de pasado sangriento cuyas víctimas se cuentan por legiones.' WHERE name_en = 'Duke''s Sinclair' AND type = 'longsword';
UPDATE equipment SET name_ja = 'アイスラーミナ', description_ja = 'イヴェルカーナの太刀。極寒の刃は 苦痛に呻く声すら即座に凍結させ、永遠の静寂を与える。', name_fr = 'Sabre de glace', description_fr = 'Épée longue de glace créée à partir de matériaux de Velkhana qui étouffe les cris de sa proie dans sa gorge.', name_it = 'Criociglio', description_it = 'Una gelida spada lunga realizzata con parti di Velkhana che congela l''ultimo grido nella gola della preda.', name_es = 'Umbral de hielo', description_es = 'Espada larga gélida hecha con elementos de Velkhana. Congela en el aire los últimos gritos de su presa.' WHERE name_en = 'Icebrink' AND type = 'longsword';
UPDATE equipment SET name_ja = 'チーズニャイフ', description_ja = 'ナイフはチーズを切り…、チーズは太刀を包む…。 ループはニャイフでカット。', name_fr = 'Couteau à fromage', description_fr = 'Au cas où vous tomberiez nez à groin avec un monstre qui ne digère pas le lactose.', name_it = 'Coltello formaggio', description_it = 'Chissà... Un giorno potresti imbatterti in un mostro intollerante al lattosio!', name_es = 'Cuchillo de queso', description_es = 'Nunca se sabe. Tal vez algún día te topes con un monstruo con intolerancia a la lactosa.' WHERE name_en = 'Cheese Knife' AND type = 'longsword';
UPDATE equipment SET name_ja = '鬼哭斬破刀', description_ja = '鬼の名を取った後、力に酔う弟子の策に散った剣士。 その悔恨と絶望が詰まった妖刀。', name_fr = 'Fendoir gémissant', description_fr = 'Épée forgée par un épéiste assoiffé de pouvoir tué par son disciple. L''épée maudite résonne désormais de ses regrets et désespoirs.', name_it = 'Katana del gemito', description_it = 'Lama intrisa di rimpianto e speranza appartenuta a un grande spadaccino ucciso dal suo discepolo.', name_es = 'Cuchillo del llanto', description_es = 'Espada forjada por un gran espadachín que pereció a manos de su discípulo. Su desesperación y pesares pueden oírse en la espada maldita.' WHERE name_en = 'Wailing Ghost' AND type = 'longsword';
UPDATE equipment SET name_ja = 'ガノスラッシャー', description_ja = '水竜の躍動感を実現した太刀。 放つ水圧が獲物を一掃する。光沢あるヒレは新鮮な証拠。', name_fr = 'Jet Plesioth', description_fr = 'Lame aussi habile qu''un Plesioth qui envoie de l''eau sous pression. Ses ailerons lui confèrent une certaine élégance.', name_it = 'Fiotto Plesioth', description_it = 'Lama agile come un Plesioth. Scaglia getti d''acqua a pressione e sfoggia eleganti pinne.', name_es = 'Salpicador Plesioth', description_es = 'Espada ágil cual Plesioth. Lanza agua a presión sin perder la elegancia gracias a sus aletas.' WHERE name_en = 'Plesioth Splasher' AND type = 'longsword';
UPDATE equipment SET name_ja = '骨刀【狼牙】', description_ja = '骨をベースに強化した太刀。 刀身の背に牙を用いて、斬撃時に深手をあたえる刀に改造。', name_fr = 'Katana os "Loup"', description_fr = 'Épée longue améliorée sur une base en os. Son bord supérieur est couvert de crocs de monstre.', name_it = 'Katana d''osso lupo', description_it = 'Spada lunga migliorata. La base è d''osso e la lama presenta zanne di mostro.', name_es = 'Katana hueso "Lobo"', description_es = 'Espada larga mejorada de base de hueso. El extremo superior lo cubren colmillos.' WHERE name_en = 'Bone Katana "Wolf"' AND type = 'longsword';
UPDATE equipment SET name_ja = '白猿薙【ドド】', description_ja = '雪獅子の素材を使用した太刀。 極寒の刀身は、近付くだけで全ての物を凍結させる。', name_fr = 'Décimeur Blango', description_fr = 'Épée longue faite à base de Blangonga. Sa lame gèle quiconque s''approche.', name_it = 'Decimatore Blango', description_it = 'Spada lunga fatta con materie Blangonga. La lama congela tutto ciò che tocca.', name_es = 'Diezmador Blango', description_es = 'Espada larga de materiales de Blangonga. Su fría hoja congela todo lo que toca.' WHERE name_en = 'Blango Decimator' AND type = 'longsword';
UPDATE equipment SET name_ja = 'クライブラッド', description_ja = '影蜘蛛の脚を思わせる細身の太刀。 獲物に気づかせずに命を絶つことができる斬れ味。', name_fr = 'Cri du sang', description_fr = 'Épée longue affûtée aussi élancée qu''une patte de Nerscylla. Furtive et mortelle.', name_it = 'Grido sanguinario', description_it = 'Lama sottile e letale come una zampa di Nerscylla, per uccisioni rapide e furtive.', name_es = 'Grito sangriento', description_es = 'Espada tan delgada y mortífera como la pata del Nerscylla. Se aproxima a sus enemigos con soltura y los mata limpiamente.' WHERE name_en = 'Blood Cry' AND type = 'longsword';
UPDATE equipment SET name_ja = 'アルシュエンシス', description_ja = 'アルシュベルドの素材で作られた太刀。 理想を求めた古の騎士は、立ちはだかる者すべてを斬り伏せた。', name_fr = 'Arkensis', description_fr = 'Épée longue fabriquée avec des matériaux d''Arkveld. Le chevalier qui la portait terrassait tous ceux qui menaçaient le royaume.', name_it = 'Ensis Veldian', description_it = 'Una spada lunga realizzata con materiali di Arkveld. Il cavaliere che la impugnava poneva fine alla vita di chiunque minacciasse il regno.', name_es = 'Arkensis', description_es = 'Espada larga hecha de materiales de Arkveld. El caballero que la blandía derribó a todo aquel que amenazó un reino idílico.' WHERE name_en = 'Veldian Ensis' AND type = 'longsword';
UPDATE equipment SET name_ja = 'レ・トニトゥラ', description_ja = 'レ・ダウの雷を纏いし太刀。素材を研いだ刃は 電気をよく通し、帯電した一閃で獲物を斬り伏せる。', name_fr = 'Rey Tonitrus', description_fr = 'Épée longue renfermant la foudre du Rey Dau. Les ennemis reculent devant sa morsure électrique.', name_it = 'Tonitrus Rey', description_it = 'Spada lunga che racchiude il tuono del Rey Dau. Gli avversari si piegano dopo un solo bacio della sua lama conduttiva.', name_es = 'Rey Tonitrus', description_es = 'Espada larga imbuida con el rayo del Rey Dau. Los adversarios se doblegan con un beso de su filo conductor.' WHERE name_en = 'Rey Tonitrus' AND type = 'longsword';
UPDATE equipment SET name_ja = 'フローズンコア', description_ja = '極寒の冷気を核に封じ込めた大槌。 あまりの低温ゆえ素手で触れる事は危険である。', name_fr = 'Cœur de glace', description_fr = 'Marteau si froid que le toucher sans protection peut geler vos mains.', name_it = 'Nucleo ghiacciato', description_it = 'Racchiude un nucleo ghiacciato e gela chiunque lo tocchi a mani nude.', name_es = 'Núcleo congelado', description_es = 'Martillo de núcleo gélido. Tan frío que, sin protección, congela las manos con solo tocarlo.' WHERE name_en = 'Frozen Core' AND type = 'hammer';
UPDATE equipment SET name_ja = '混沌の鎚', description_ja = '恐暴竜の力がにじみ出るハンマー。 閉じ込められた怒りは獲物を求めその姿を大きく隆起させる。', name_fr = 'Marteau du Chaos', description_fr = 'Marteau empli de la puissance du Deviljho. La rage scellée en son sein le fait gonfler à la vue d''une proie.', name_it = 'Patto diabolico', description_it = 'Martello che trasuda la potenza del Deviljho. La rabbia che racchiude ingrandisce l’arma alla vista della preda.', name_es = 'Diablo Sediento', description_es = 'Martillo del que emana el poder del Deviljho. La ira confinada en su interior hincha el arma cuando avista su presa.' WHERE name_en = 'Devil''s Due' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ディオステイル', description_ja = 'ブラキディオスの尾を加工した、爆発性の粘菌を まとったハンマー。衝撃により粘菌が飛び散る。', name_fr = 'Marteau queue Dios', description_fr = 'Marteau forgé à partir d''une queue de Brachydios. Chaque impact libère une substance explosive dans l''air.', name_it = 'Coda-flagello Dios', description_it = 'Martello realizzato con la coda di un Brachydios. A ogni colpo, una melma infiammabile si libera nell''aria.', name_es = 'Martillo cola Brach', description_es = 'Martillo forjado con la cola de un Brachydios. Cada uno de sus golpes proyecta en el aire una explosión de cieno.' WHERE name_en = 'Dios Tailhammer' AND type = 'hammer';
UPDATE equipment SET name_ja = '灼炎のイシャター', description_ja = '鎚頭に尋常ならざる熱量を宿す暗紅の鉄鎚。 打ち砕け、その鎚の名は灼炎のイシャター。', name_fr = 'Isshata brûlant', description_fr = 'Marteau forgé avec le feu de l''enfer. Fracasse avec une fureur incontrôlable.', name_it = 'Isshata ardente', description_it = 'La testa di questo martello emana un calore che non conosce confini.', name_es = 'Isshata abrasadora', description_es = 'Martillo cuya cabeza presenta un calor extremo que no conoce límites.' WHERE name_en = 'Scorching Isshata' AND type = 'hammer';
UPDATE equipment SET name_ja = 'クルルビーク', description_ja = 'クルルヤックの堅いクチバシを加工したハンマー。 こんな堅いもので思いきり叩かれたらひとたまりもない。', name_fr = 'Bec Kulu', description_fr = 'Marteau conçu à partir d''un solide bec de Kulu-Ya-Ku. Quiconque frappé ne se relèvera pas de sitôt.', name_it = 'Becco Kulu', description_it = 'Martello ricavato dal becco di un Kulu-Ya-Ku. Atterra il bersaglio impedendogli di rialzarsi per un po''.', name_es = 'Pico Kulu', description_es = 'Martillo hecho con el firme pico de un Kulu-Ya-Ku. Cualquiera que reciba un golpe tardará un buen rato en poder levantarse.' WHERE name_en = 'Kulu Beak' AND type = 'hammer';
UPDATE equipment SET name_ja = '天具・五鈷の槌', description_ja = '天狗獣のひときわ堅固な素材で作られた鎚。 煩悩を打ち破りその身を守ると言われる法具。', name_fr = 'Marteau à pics', description_fr = 'Marteau fait en Bishaten. On dit qu''il protège ceux qui ne sont pas corrompus par l''avidité.', name_it = 'Martello cinquepunte', description_it = 'Martello fatto con parti di Bishaten. Si narra protegga i generosi di cuore.', name_es = 'Martillo cinco puntas', description_es = 'Martillo hecho de partes de Bishaten. Se dice que protege a los que no son avariciosos.' WHERE name_en = 'Five-Pronged Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'メロウブロウ', description_ja = '打擲部を掻き抱くような掌の形状が特徴の鎚。 殴られた者は人魚の黒い情念に襲われる。', name_fr = 'Marteau à volants', description_fr = 'Marteau en Somnacanth. Frappe ses victimes avec la force sombre d''une sirène.', name_it = 'Martello crestato', description_it = 'Martello ricavato da parti di Somnacanth. Colpisce col cupo fervore di una sirena.', name_es = 'Martillo crestado', description_es = 'Martillo hecho de partes de Somnacanth. Golpea con el oscuro fervor de una sirena.' WHERE name_en = 'Frilled Blow' AND type = 'hammer';
UPDATE equipment SET name_ja = '禍ツ槌【封】', description_ja = '甲冑を思わせる形状と鬼の如き紋様。 破壊の一途を辿りながら怨虎竜の鎚は何を思うか…。', name_fr = 'Marteau sinistre', description_fr = 'Marteau fait à partir de Magnamalo. Cette arme démoniaque prend l''apparence d''une ancienne armure, ouvrant la voie à la destruction.', name_it = 'Martello sinistro', description_it = 'Martello fatto di parti del Magnamalo. È un''arma infernale a forma di un''armatura antica che segna un percorso di distruzione.', name_es = 'Martillo siniestro', description_es = 'Martillo hecho de partes de Magnamalo. Un arma demoníaca que tiene la forma de una armadura antigua, abriendo camino a la destrucción.' WHERE name_en = 'Sinister Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ゴシャベチャ', description_ja = '外見から「氷の塊」と呼ばれる雪鬼獣の槌。 難しく考えず、本能のまま獲物をベチャッ！！', name_fr = 'Marteau du yéti', description_fr = 'Marteau Goss Harag glacial. Déchaînez vos pulsions primitives et écrasez vos ennemis !', name_it = 'Martello Yeti', description_it = 'Martello ghiacciato fatto di Goss Harag. Segui l''istinto e annienta gli avversari!', name_es = 'Martillo de yeti', description_es = 'Martillo helado de Goss Harag. ¡Deja libres tus instintos y aplasta a tus enemigos!' WHERE name_en = 'Yeti Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'Ｄ＝スィ', description_ja = '泥翁竜の素材を用いた鎚。 回転する強烈な一撃は、獲物を前後不覚にさせるほどの威力。', name_fr = 'Marteau Almudron', description_fr = 'Marteau fait en Almudron. Terrasse férocement ses adversaires sans distinction.', name_it = 'Martello Almudron', description_it = 'Martello ricavato da parti di Almudron. La sua inaudita ferocia distrugge i nemici.', name_es = 'Martillo Almudron', description_es = 'Martillo hecho de partes de Almudron. Su ferocidad somete a todos los enemigos.' WHERE name_en = 'Almudron Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'あかしまの神槌', description_ja = '蒼き鎚の凄まじき容貌は風巻の龍の憤怒が具現。 重打は地維を揺るがし、昊天を断ち割る。', name_fr = 'Marteau ancien azur', description_fr = 'Marteau qui symbolise la rage de l''Ibushi. Il ébranle la terre avec un simple coup.', name_it = 'Martello dell''anziano celeste', description_it = 'Incarnazione dell''ira dell''Ibushi. Ogni suo colpo riesce a scuotere la terra.', name_es = 'Martillo de anciano añil', description_es = 'Martillo que encarna la ira de Ibushi. Un simple golpe puede sacudir la tierra.' WHERE name_en = 'Azure Elder Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = '工房試作品ガンハンマ', description_ja = '遠方の街の工房で開発された機械鎚。 その技術力は多くの鍛冶工房を驚嘆させたという。', name_fr = 'Proto Marteauflingue', description_fr = 'Fabriqué dans une ville lointaine, ce marteau fait beaucoup de jaloux.', name_it = 'Prototipo mart.-fuc.', description_it = 'Fatto in una città lontana, molte officine invidiano questo martello.', name_es = 'Prototipo martillo pistola', description_es = 'Martillo hecho en una ciudad lejana. Es la envidia de muchos talleres.' WHERE name_en = 'Gunhammer Prototype' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ボーンハンマー', description_ja = '骨の塊を加工して作られたハンマー。 金属製のものと比べると軽くて扱いやすい。', name_fr = 'Marteau en os', description_fr = 'Marteau fabriqué à base d''os. Plus léger et plus facile d''utilisation que ses équivalents en métal.', name_it = 'Martello d''osso', description_it = 'Martello ricavato da un osso. Più leggero e maneggevole rispetto a quelli di metallo.', name_es = 'Martillo de hueso', description_es = 'Martillo hecho de hueso. Más ligero y fácil de usar que los martillos de metal.' WHERE name_en = 'Bone Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'デスグラシア', description_ja = '災いを招くという悪霊の手を模した武器。 掴まれた者は訪れる災厄から逃れられない。', name_fr = 'Mort gracieuse', description_fr = 'Arme évoquant la main d''un esprit vengeur. Saisit les âmes de ses victimes.', name_it = 'Morte soave', description_it = 'Arma che ricorda la mano di uno spirito vendicativo. Stritola le anime che miete.', name_es = 'Muerte digna', description_es = 'Arma con forma de mano de un espíritu vengativo. Aferra las almas de sus víctimas.' WHERE name_en = 'Graceful Death' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ドロスボアハンマー', description_ja = '水獣の海綿質を用いた大鎚。 蓄えた水分はヒットした衝撃を受け対象の表皮上で爆散する。', name_fr = 'Aquamarteau Ludroth', description_fr = 'Marteau fait à partir de matériaux spongieux de Ludroth. L''eau qu''il contient explose sur la cible à son contact.', name_it = 'Mart. fiotto Ludroth', description_it = 'Fatto con le parti spugnose di Ludroth. Contiene acqua che esplode quando centra il bersaglio.', name_es = 'Martillo esponjoso Ludroth', description_es = 'Martillo hecho de materiales esponjosos de Ludroth. El agua de su interior explota en el objetivo al impactar.' WHERE name_en = 'Ludroth Splashhammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'カラミティーサイン', description_ja = '翼蛇竜が絡み合うかのような不吉な鎚。 その姿は、まさしく厄災の前触れを思わせる。', name_fr = 'Augure calamiteux', description_fr = 'Marteau aussi mystérieux que menaçant, orné de trois Remobra entrelacés.', name_it = 'Prodigio calamitoso', description_it = 'Inquietante martello con tre Remobra intrecciati. Sembra un presagio di morte.', name_es = 'Presagio calamitoso', description_es = 'Martillo espeluznante con tres Remobra entrelazados. Se siente premonitorio.' WHERE name_en = 'Calamitous Portent' AND type = 'hammer';
UPDATE equipment SET name_ja = '王鎚カミナリ', description_ja = '雷雲を従える鬼神の顔を模したという大鎚。 怒れる王者の一撃にあまたの命が塵と化す。', name_fr = 'Tonnerre du roi', description_fr = 'Marteau Zinogre. Un coup suffit à réduire d''innombrables vies à néant.', name_it = 'Tuono del tiranno', description_it = 'Martello modellato su un demone del tuono. Polverizza eserciti con un solo colpo.', name_es = 'Rayo del usurpador', description_es = 'Martillo fabricado a partir de un Zinogre. Un solo golpe puede reducir a polvo toda clase de vida.' WHERE name_en = 'Usurper''s Thunder' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ブロスハンマー', description_ja = 'ディアブロスの尻尾を丸ごとハンマーの素材にした殻鎚。 優れた斬れ味を誇る業物。', name_fr = 'Marteau Diablos', description_fr = 'Marteau fait d''une queue de Diablos entière. Ce chef-d''œuvre est doté d''une incroyable puissance destructrice.', name_it = 'Martello Diablos', description_it = 'Martello realizzato con un''intera coda di Diablos. Questo capolavoro vanta un potere distruttivo devastante.', name_es = 'Martillo Diablos', description_es = 'Martillo fabricado con la totalidad de la cola de un Diablos. Una obra maestra que cuenta con un poder destructivo devastador.' WHERE name_en = 'Diablos Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ギザミヘッドアクス', description_ja = '加工が最も困難な鎌蟹の頭の甲殻を使用した逸品。 弾かれにくさを重視して設計された。', name_fr = 'Hache tête Ceanataur', description_fr = 'Fait de morceaux de tête de Shogun durs à façonner. Conçu pour la maniabilité.', name_it = 'Scure Ceanataur', description_it = 'Creata con parti di crani di Shogun. Molto solida e facile da usare.', name_es = 'Hacha cabeza Ceanataur', description_es = 'Obra de arte hecha de duras piezas de la cabeza de Shogun. Diseñada priorizando la facilidad de uso.' WHERE name_en = 'Ceanataur Head Axe' AND type = 'hammer';
UPDATE equipment SET name_ja = 'マトラカアルグル', description_ja = '千刃竜の鱗を組み合わせた鎚。 極めて高い強度と鋭利な棘で攻撃対象を粉塵と化す。', name_fr = 'Marteau Matraca', description_fr = 'Forgé en écailles de Seregios. Réduit les ennemis en poussière.', name_it = 'Martello Matraca', description_it = 'Martello forgiato con scaglie di Seregios. È capace di ridurre i nemici in polvere.', name_es = 'Martillo matraca', description_es = 'Martillo forjado con escamas de Seregios. Capaz de hacer polvo a sus víctimas.' WHERE name_en = 'Matraca Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'エムロードビート', description_ja = 'ライゼクスの鶏冠を模したハンマー。 電竜の暴虐を恐れぬ者のみが所持できる。', name_fr = 'Frappeur émeraude', description_fr = 'Marteau s''inspirant de la crête d''un Astalos. Seuls ceux qui ne craignent pas la wyverne de foudre peuvent le maîtriser.', name_it = 'Battitore smeraldo', description_it = 'Martello a forma di cresta di Astalos. Solo chi non teme il wyvern del tuono è degno di brandirlo.', name_es = 'Batidor esmeralda', description_es = 'Martillo moldeado con la cresta de un Astalos. Solo es digno de quienes no teman a este wyvern de elemento rayo.' WHERE name_en = 'Emerald Beater' AND type = 'hammer';
UPDATE equipment SET name_ja = 'デュークスマイト', description_ja = '爵銀龍の槌。殺傷力を高めるために先端が尖っており、 獲物を骨の髄まで砕き散らす。', name_fr = 'Duc cogneur', description_fr = 'Marteau Malzeno. Sa pointe plus létale broie l''os jusqu''à la moelle.', name_it = 'Distruttore ducale', description_it = 'Martello di Malzeno, reso più letale dalla punta affusolata che distrugge fino al midollo.', name_es = 'Arrasador ducal', description_es = 'Martillo de Malzeno con una punta afilada y letal que se clava hasta la médula.' WHERE name_en = 'Duke Smiter' AND type = 'hammer';
UPDATE equipment SET name_ja = '冷たき月の砕鎚', description_ja = '氷狼竜の凶暴性を体現した槌。 獲物の前で構えると、血肉を欲するかのように冷気を放つ。', name_fr = 'Marteau hivernal', description_fr = 'Marteau qui symbolise la férocité du Lunagaron. L''air froid qu''il relâche annonce un carnage.', name_it = 'Martello di luna fredda', description_it = 'Martello dall''immensa ferocia. Rilascia aria fredda, anticipando il massacro.', name_es = 'Martillo luna invernal', description_es = 'Martillo imbuido con la ferocidad del Lunagaron. Despide aire frío como preámbulo a la matanza.' WHERE name_en = 'Hammer of Winter Moon' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ゴルム・ガベル', description_ja = '大きな戦槌から放たれる一撃は剛纏獣が 腕を振り下ろしたかのような激しい衝撃を生み出す。', name_fr = 'Maillet Golm', description_fr = 'Marteau infligeant des coups puissants et des ondes de choc comme le ferait un Garangolm.', name_it = 'Martelletto Garangolm', description_it = 'Martello capace di assestare colpi potenti simili alle onde d''urto di un Garangolm.', name_es = 'Martillo de Garangolm', description_es = 'Martillo capaz de desatar duros golpes y ondas sísmicas como si fuera un Garangolm.' WHERE name_en = 'Golm Gavel' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ローゼンハンマー', description_ja = 'エスピナスの頭部を豪快に使用したハンマー。 棘竜の怒りが、何もかもを粉砕する。', name_fr = 'Rosenhammer', description_fr = 'Marteau utilisant la tête d''un Espinas. Sa rage piquante écrase tout sur son passage.', name_it = 'Rosenhammer', description_it = 'Martello che sfrutta una testa di Espinas. La sua ira spinosa distrugge tutto.', name_es = 'Rosenmartillo', description_es = 'Martillo que golpea con la cabeza de un Espinas. Su ira punzante lo arrasa todo.' WHERE name_en = 'Rosenhammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'クックピック', description_ja = 'みんなに大人気！　イャンクックのハンマー！ これを持てばあなたも立派な怪鳥マニア！', name_fr = 'Pic Kut-Ku', description_fr = 'Le marteau de Yian Kut-Ku incontournable de cette saison. Maniez-le avec fierté et affichez votre amour pour les Kut-Ku !', name_it = 'Piccone Kut-Ku', description_it = 'Imperdibile martello di Yian Kut-Ku. Da brandire con orgoglio, se ti piacciono i Kut-Ku.', name_es = 'Pico de Kut-Ku', description_es = 'El martillo de Yian Kut-Ku imprescindible de esta temporada. Empúñalo con orgullo y demuestra que te pirran los Kut-Ku.' WHERE name_en = 'Kut-Ku Pick' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ガノヘッド', description_ja = '水の中を自在に泳ぐ水竜の頭を模したハンマー。 全てを飲み込む激流の勢いで獲物に襲いかかる。', name_fr = 'Tête Plesioth', description_fr = 'Marteau conçu sur le modèle d''une tête de Plesioth. Libère la puissance d''un torrent à chaque attaque.', name_it = 'Testa Plesioth', description_it = 'Martello ispirato alla testa di un Plesioth. Colpisce con la forza di un fiume impetuoso.', name_es = 'Cabeza de Plesioth', description_es = 'Martillo fabricado con la cabeza de un Plesioth. Ataca con la fuerza de un río bravo.' WHERE name_en = 'Plesioth Head' AND type = 'hammer';
UPDATE equipment SET name_ja = 'シェルハンマー', description_ja = 'グラビモスの甲殻で作られたハンマー。 大きな鎚頭に付いた複数の棘に恐れ、獲物は逃げ回る。', name_fr = 'Marteau coquille', description_fr = 'Marteau fabriqué à partir d''une carapace de Gravios. La simple vue de ses innombrables pointes fait paniquer ses proies.', name_it = 'Martello corazza', description_it = 'Martello ricavato dal carapace di un Gravios. Terrorizza le prede alla sola vista degli spuntoni sulla testa.', name_es = 'Martillo caparazón', description_es = 'Martillo hecho con el caparazón de un Gravios. Sus presas entran en pánico al ver los múltiples pinchos de su cabeza.' WHERE name_en = 'Shell Hammer' AND type = 'hammer';
UPDATE equipment SET name_ja = 'ヴェノムモンスター', description_ja = '別名「毒の怪物」とも呼ばれる異形のハンマー。 強力な毒が仕込まれている、恐ろしい武器。', name_fr = 'Monstre venimeux', description_fr = 'Marteau réputé pour son apparence inhabituelle. Une arme terrifiante contenant un poison mortel.', name_it = 'Mostro velenoso', description_it = 'Martello noto per il suo aspetto bizzarro. Un’arma terrificante che contiene un veleno mortale.', name_es = 'Monstruo de veneno', description_es = 'Martillo que destaca por su aspecto fuera de lo común. Un arma terrorífica que encierra un veneno mortal.' WHERE name_en = 'Venom Monster' AND type = 'hammer';
