UPDATE equipment SET name_ja = '狐鈴コトノハナクテ', description_ja = '軍師として名を馳せた士が遺した雅なる鈴。 その鈴の音は静かに響き、遠逝を誘う。', name_fr = 'Cloche poétique', description_fr = 'Belle cloche laissée par un célèbre stratège. Son glas cristallin annonce la mort.', name_it = 'Campana poetica', description_it = 'Campana perduta da un famoso stratega. Il suo timbro cristallino attira la morte.', name_es = 'Campana poética', description_es = 'Elegante campana de un famoso estratega militar. Su tono nítido augura la muerte.' WHERE name_en = 'Poetic Bell' AND type = 'horn';
UPDATE equipment SET name_ja = '火竜笛アンビシオン', description_ja = '王こそが勝者、勝者こそが王。 強化により磨かれた音色は勝利を呼び、王への標となる。', name_fr = 'Ire du Rathalos', description_fr = 'Un vrai roi ne connaît nulle défaite. Cet instrument raffiné annonce la victoire et ouvre la voie à la domination avec ses mélodies audacieuses.', name_it = 'Feroce Rathalos', description_it = 'Un vero re non conosce la sconfitta. Questo strumento annuncia la vittoria e spiana la strada al dominio con le sue audaci melodie.', name_es = 'Rathalos feroz', description_es = 'Un verdadero rey no conoce la derrota. Con sus intensas melodías, este instrumento anuncia la victoria y allana el camino hacia la dominación.' WHERE name_en = 'Rathalos Feroce' AND type = 'horn';
UPDATE equipment SET name_ja = 'エムロードフラップ', description_ja = '電竜の翼膜で創製された、狩猟笛。 猛き雷が内部で共鳴し周囲に荒々しく響き渡る。', name_fr = 'Batteur émeraude', description_fr = 'Corne de chasse fabriquée à partir d''une membrane d''aile d''Astalos. Elle résonne comme un puissant tonnerre.', name_it = 'Volo smeraldo', description_it = 'Corno da caccia prodotto con le membrane alari di un Astalos. Riecheggia con forza tonante.', name_es = 'Aleta esmeralda', description_es = 'Cornamusa hecha con la membrana del ala de un Astalos. Emite un estruendo que resuena como un trueno ensordecedor.' WHERE name_en = 'Emerald Flap' AND type = 'horn';
UPDATE equipment SET name_ja = 'デュークグレイル', description_ja = '爵銀龍の素材でできた狩猟笛。 その音色は清廉なようであり、どこか怪しげなようでもある。', name_fr = 'Graal du Duc', description_fr = 'Corne de chasse forgée de matériaux de Malzeno. Ses mélodies sont innocentes et mystérieuses.', name_it = 'Graal del duca', description_it = 'Corno da caccia dalle melodie innocenti e misteriose, forgiato con materiali di Malzeno.', name_es = 'Grial ducal', description_es = 'Cornamusa hecha con materiales provenientes de Malzeno. Sus melodías son tan inocentes como misteriosas.' WHERE name_en = 'Duke''s Grail' AND type = 'horn';
UPDATE equipment SET name_ja = 'ゴルム・ドラム', description_ja = '剛纏獣の硬い素材で作られた狩猟笛。 爆発的な音圧を放ち、聴く物の心臓にまで響く。', name_fr = 'Tambour Golm', description_fr = 'Tambour Garangolm dont le son explosif touche l''âme de ceux qui les entendent.', name_it = 'Tamburo sismico', description_it = 'I suoni esplosivi di questo corno da caccia toccano l''anima di chi li ascolta.', name_es = 'Tambor de Garangolm', description_es = 'El sonido explosivo de este tambor de Garangolm hace eco en el corazón de quienes lo oyen.' WHERE name_en = 'Golm Drum' AND type = 'horn';
UPDATE equipment SET name_ja = 'アイスシュピール', description_ja = 'イヴェルカーナの素材を用いて作られた狩猟笛。極寒の一撃は 苦痛に呻く声すら即座に凍結させ、永遠の静寂を与える。', name_fr = 'Sentence de glace', description_fr = 'Corne de chasse de glace créée à base de matériaux de Velkhana qui étouffe les cris de sa proie dans sa gorge.', name_it = 'Crioassillo', description_it = 'Un corno da caccia gelido realizzato con parti d Velkhana che congela l''ultimo grido nella gola della preda.', name_es = 'Discurso de hielo', description_es = 'Cornamusa gélida hecha con elementos de Velkhana. Congela en el aire los últimos gritos de su presa.' WHERE name_en = 'Icespiel' AND type = 'horn';
UPDATE equipment SET name_ja = 'シャミセン【烏】', description_ja = 'イャンガルルガの尻尾を丸ごと活かした武器。 三本の弦から溢れる音は、どこか物悲しい。', name_fr = 'Shamisen rapace', description_fr = 'Faite à partir d''une queue entière de Yian Garuga. Ses trois cordes jouent une mélodie mélancolique.', name_it = 'Shamisen corvo', description_it = 'Realizzato con l''intera coda di uno Yian Garuga. Le sue tre corde liberano struggenti melodie.', name_es = 'Shamisen azabache', description_es = 'Fabricada con la cola de un Yian Garuga. Una melodía melancólica emana de sus tres cuerdas.' WHERE name_en = 'Raven Shamisen' AND type = 'horn';
UPDATE equipment SET name_ja = 'クックソング', description_ja = '怪奇な歌声に野辺燃え立つ、イャンクックの狩猟笛。 怪鳥が内に秘めし力のほどを見よ。', name_fr = 'Chanson Kut-Ku', description_fr = 'Corne de chasse dont la mélodie bouleverse les cœurs les plus endurcis.', name_it = 'Canto Kut-Ku', description_it = 'Corno da caccia che usa il suo potere speciale per risollevare il cuore di chi ne ascolta la melodia.', name_es = 'Canción de Kut-Ku', description_es = 'Cornamusa que usa su poder especial para conmover el corazón de quienes escuchan su canción.' WHERE name_en = 'Kut-Ku''s Song' AND type = 'horn';
UPDATE equipment SET name_ja = '毒笛カプリ', description_ja = 'クチバシを打ち鳴らし獲物を威嚇する、毒怪鳥の狩猟笛。 その美しい瞳で、獲物の最期を見届ける。', name_fr = 'Capri empoisonné', description_fr = 'Corne de chasse faite à partir de matériaux de Gypceros, inspirée de la crête et du bec uniques de la créature.', name_it = 'Capricorno avvelenato', description_it = 'Corno da caccia realizzato con parti di Gypceros. Si ispira al becco e alla cresta del mostro.', name_es = 'Capri envenenado', description_es = 'Cornamusa hecha con partes de Gypceros. Imita, sobre todo, sus excepcionales pico y cresta.' WHERE name_en = 'Poisoned Capri' AND type = 'horn';
UPDATE equipment SET name_ja = 'ドドットボロン', description_ja = '極寒を生きる民族が白きヌシのお告げを聞く際に奏でる祭器。 雪原にヌシの声が響き渡る。', name_fr = 'Corne Dodotto', description_fr = 'Instrument traditionnel utilisé par les tribus montagnardes de vallées enneigées.', name_it = 'Corno Dodotto', description_it = 'Strumento tradizionale usato dalle tribù che vivono nelle terre del monte artico.', name_es = 'Cuerno Dodotto', description_es = 'Instrumento tradicional usado por tribus que habitan en las montañas nevadas.' WHERE name_en = 'Dodotto Horn' AND type = 'horn';
UPDATE equipment SET name_ja = '６３式軍楽口風琴', description_ja = '工匠団による特殊設計の狩猟笛。 音色で指揮を執ることで、統率のとれた狩猟を完遂する。', name_fr = 'Warmonica T-63', description_fr = 'Arme musicale de fabrication artisanale. Ses airs peuvent guider les gestes en pleine chasse.', name_it = 'Armonica T-63', description_it = 'Arma musicale di fattura artigianale. Coordina i movimenti della caccia con le sue note.', name_es = 'Guermónica tipo 63', description_es = 'Arma musical de diseño artesanal. Sus tonos dirigen movimientos en plena caza.' WHERE name_en = 'Type 63 Warmonica' AND type = 'horn';
UPDATE equipment SET name_ja = '龍木ノ笛【宿神】', description_ja = '極東の技法により不思議な調べを奏でる大笛。 龍を呼ぶための道具であるという。', name_fr = 'Cor esprit bois-dragon', description_fr = 'Cor étrange, fruit de techniques orientales. On dit qu''il pourrait appeler un dragon.', name_it = 'Corno spirito in legno di drago', description_it = 'Uno strano corno frutto di tecniche orientali. Si dice che possa evocare un drago.', name_es = 'Cuerno madera de dragón espiritual', description_es = 'Extraño cuerno elaborado con técnicas orientales. Puede llamar a un dragón.' WHERE name_en = 'Spirit Dragonwood Horn' AND type = 'horn';
UPDATE equipment SET name_ja = 'アルシュシビーロス', description_ja = 'アルシュベルドの素材で作られた狩猟笛。ただ他者のために 闘い続けた騎士は死して聖人と奉られ伝説となった。', name_fr = 'Arksibilus', description_fr = 'Corne de chasse fabriquée avec des matériaux d''Arkveld. Protecteur du peuple, son porteur est entré dans l''Histoire et a été sanctifié.', name_it = 'Sibilus Veldian', description_it = 'Un corno da caccia realizzato con materiali di Arkveld. Il cavaliere che lo ha posseduto fu santificato e divenne leggenda.', name_es = 'Arksibilus', description_es = 'Cornamusa hecha de materiales de Arkveld. Su caballero, un eterno siervo de la gente, fue canonizado y se convirtió en leyenda.' WHERE name_en = 'Veldian Sibilus' AND type = 'horn';
UPDATE equipment SET name_ja = '赫炎の笛', description_ja = 'アジャラカンの力を秘めし狩猟笛。 熱く響かせた振動は空を伝わり、届いた者に闘志を与える。', name_fr = 'Réverbérateur Ajara', description_fr = 'Corne de chasse Ajarakan dont les vibrations cinglantes secouent les cieux et embrasent l''esprit des ennemis.', name_it = 'Riverberatore Ajara', description_it = 'Corno da caccia di Ajarakan che fa tremare i cieli con vibrazioni violente, accendendo gli spiriti di chi lo ascolta.', name_es = 'Reverberador Ajara', description_es = 'Cornamusa de Ajarakan que hace temblar los cielos con vibraciones abrasadoras que encienden los espíritus de quienes las oyen.' WHERE name_en = 'Ajara Reverberator' AND type = 'horn';
UPDATE equipment SET name_ja = 'レ・ブリスビッツァ', description_ja = 'レ・ダウの雷を纏いし狩猟笛。その轟音は 君主たる者の存在を示し、耳にした生物は恐怖に震え上がる。', name_fr = 'Rey Perun', description_fr = 'Corne de chasse renfermant la foudre du Rey Dau. Elle annonce la venue d''un seigneur et provoque la peur.', name_it = 'Perun Rey', description_it = 'Corno da caccia che racchiude il tuono del Rey Dau. I suoi inni annunciano l''arrivo di un signore e suscitano paura.', name_es = 'Rey Perun', description_es = 'Cornamusa imbuida con el rayo del Rey Dau. Sus himnos anuncian la llegada de un soberano y evocan miedo.' WHERE name_en = 'Rey Perun' AND type = 'horn';
UPDATE equipment SET name_ja = 'ブロスホーンボウ', description_ja = 'ディアブロスの双角を用いた強靱な狩猟弓。 弦を引き絞るために多大な力を要する。', name_fr = 'Spire Diablos', description_fr = 'Arc fait à partir des cornes jumelles résistantes de Diablos. Il faut une force titanesque pour réussir à le bander.', name_it = 'Arcorno Diablos', description_it = 'Arco realizzato con le resilienti corna gemelle del Diablos. Richiede una forza notevole per essere usato.', name_es = 'Doblamallas Diablos', description_es = 'Arco hecho a partir de los robustos cuernos gemelos de un Diablos. Tensarlo requiere una fuerza titánica.' WHERE name_en = 'Diablos Coilbender' AND type = 'bow';
UPDATE equipment SET name_ja = 'グレイスアロー', description_ja = '大空を優雅に漂う風漂竜の弓。 銀花の矢先に射貫かれ、辺りは白銀と化す。', name_fr = 'Flèche polaire', description_fr = 'Un arc de Legiana. Ses flèches gelées transpercent la proie et l''enveloppent d''un calme mortel et glacial.', name_it = 'Freccia glaciale', description_it = 'Arco di Legiana. Quando le sue frecce glaciali trafiggono la preda, cala un silenzio di gelo.', name_es = 'Flecha Glacial', description_es = 'Arco del grácil surcador de cielos Legiana. Las flechas de hielo sumen a la presa en una fría quietud cuando la atraviesan.' WHERE name_en = 'Glacial Arrow' AND type = 'bow';
UPDATE equipment SET name_ja = '飛雷弓イテカガチ', description_ja = '飛雷竜の鱗から造られた弓。 矢を放つ際に発生する静電気を帯電素材により増幅している。', name_fr = 'Arc de foudre Kadachi', description_fr = 'Arc en Tobi-Kadachi amplifiant l''électricité statique produite lors des tirs.', name_it = 'Arco Kadachi', description_it = 'Con scaglie elettrificate di Tobi-Kadachi, amplifica l''energia elettrica prodotta scoccando i dardi.', name_es = 'Arco de ataque Kadachi', description_es = 'Arco hecho con escamas de Tobi-Kadachi. Amplifica la electricidad estática al disparar.' WHERE name_en = 'Kadachi Strikebow' AND type = 'bow';
UPDATE equipment SET name_ja = '暴徒の凶弓', description_ja = '激憤する恐王を封じた恐暴竜の弓。 野に放たれた矢は、全ての獲物を喰らい尽くす。', name_fr = 'Arc de l''Insurgé', description_fr = 'Les flèches de cet arc ont l''air d''avoir autant soif de sang que le terrifiant Deviljho, dont l''esprit est scellé à l''intérieur.', name_it = 'Arco ribelle', description_it = 'Le frecce scoccate da quest''arco bramano nuove prede come il terribile Deviljho, il cui spirito è racchiuso nell''arma.', name_es = 'Arco Insurrecto', description_es = 'Las flechas de este arco persiguen a las presas con la misma voracidad que el temible Deviljho, cuyo espíritu albergan.' WHERE name_en = 'Insurgent''s Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'ヒドゥンボウ', description_ja = '夜陰に紛れる黒の狩猟弓。 可視光を吸収する迅竜の毛は、暗闇での狙撃に極めて効果的。', name_fr = 'Arc occulte', description_fr = 'Arc en ébène pour snipers. La fourrure de Nargacuga absorbe la lumière.', name_it = 'Arco occulto', description_it = 'Arco d''ebano perfetto per i cecchini. La pelliccia di Nargacuga assorbe la luce.', name_es = 'Arco oculto', description_es = 'Arco de ébano negro como la noche. La piel de Nargacuga lo hace casi invisible.' WHERE name_en = 'Hidden Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'ヒドラ・プラヌラ', description_ja = 'ネロミェールの弓。弓の漆黒は深さの見えぬ闇。 明滅する光は、深淵に誘う妖しい輝き。', name_fr = 'Planula hydra', description_fr = 'Arc Namielle noir de jais. Sa lueur est une invitation à rejoindre les abysses.', name_it = 'Planula Idra', description_it = 'La flebile luce irradiata dal nero arco di Namielle è un invito a cedere all''abisso.', name_es = 'Plánula Hidra', description_es = 'La tenue luz que brilla en este negro arco de Namielle es una invitación al abismo.' WHERE name_en = 'Hydra Planula' AND type = 'bow';
UPDATE equipment SET name_ja = '鉄弓', description_ja = '鉄を手早く加工して作った弓。 量産型ゆえに荒さが目立つが、素人でもそれ相応の一矢が放てる。', name_fr = 'Arc en fer', description_fr = 'Arc en fer brut. Une arme simple particulièrement prisée par les chasseurs débutants.', name_it = 'Arco di ferro', description_it = 'Rudimentale arco di ferro, prodotto in serie ma dotato di notevole potenza.', name_es = 'Arco Férreo', description_es = 'Arco de hierro que, a pesar de producirse a escala masiva, es bastante poderoso.' WHERE name_en = 'Iron Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'フラムエルアルクス', description_ja = '蛮顎竜の翼と牙から作られた狩猟弓。 放たれた矢は火の雨となって情け容赦なく降り注ぐ。', name_fr = 'Flammenbogen', description_fr = 'Façonné en ailes et crocs d''Anjanath, cet arc fait pleuvoir un déluge de feu.', name_it = 'Flammenbogen', description_it = 'Arco creato con zanne e ali di Anjanath. Scaglia una pioggia di frecce.', name_es = 'Flammenbogen', description_es = 'Hecho de colmillos y alas de Anjanath, este arco dispara una lluvia de flechas fundidas.' WHERE name_en = 'Flammenbogen' AND type = 'bow';
UPDATE equipment SET name_ja = '天具・光背の弓', description_ja = '天狗獣の蒼い羽を加工した弓。 背負うと輪状の部位が後光のようになって、尊く見える。', name_fr = 'Rayon de l''aube', description_fr = 'Fait en plumes bleues de Bishaten. Porté sur le dos, il ressemble à un halo, brillant d''un éclat propre à la noblesse.', name_it = 'Arco raggialba', description_it = 'Realizzato in piume blu di Bishaten. Assomiglia a un''aureola sulla schiena, che brilla di nobiltà.', name_es = 'Arco rayo del alba', description_es = 'Arco hecho con plumas azules de Bishaten. Resplandece con nobleza a tu espalda como si de un halo se tratase.' WHERE name_en = 'Dawn Ray Bow' AND type = 'bow';
UPDATE equipment SET name_ja = '禍ツ弓【封】', description_ja = 'ただただ狩って喰らう怨虎竜の情念を封じた弓。 殺戮の果てに生まれるは、新たなる怨恨…。', name_fr = 'Arc sinistre', description_fr = 'Abrite la rage du Magnamalo. Sa rancœur s''accroît à chacune de ses victimes.', name_it = 'Arco sinistro', description_it = 'Custodisce l''animo impetuoso del Magnamalo. Il massacro alimenta la furia...', name_es = 'Arco siniestro', description_es = 'Encierra la vehemencia del Magnamalo. La matanza alimenta el rencor...' WHERE name_en = 'Sinister Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'Ｄ＝シャ', description_ja = '泥翁竜の素材を用いた弓。 素材の持つ独特なしなりを、金属部品が倍増させている。', name_fr = 'Tir boueux', description_fr = 'Arc en Almudron. Le métal utilisé renforce la courbure de cette arme.', name_it = 'Colpo fangoso', description_it = 'Arco con parti di Almudron. Le parti in metallo esaltano la tipica curvatura.', name_es = 'Disparo fangoso', description_es = 'Arco de restos de Almudron. Los refuerzos de metal propician su curvatura.' WHERE name_en = 'Mud Shot' AND type = 'bow';
UPDATE equipment SET name_ja = '真誠なるケアアルク', description_ja = '福音を放つ妃蜘蛛の火弓は、心を射抜いて身体を燃やす。 深き情念の糸に引かれて…。', name_fr = 'Toile incandescente', description_fr = 'Nimbé d''un feu purifiant, cet arc transperce et brûle le cœur de ses victimes. Nul ne peut échapper aux toiles de son désir.', name_it = 'Tessitore di fiamme', description_it = 'Avvolto nelle fiamme dell''assoluzione, l''arco della vedova nomade trafigge il cuore e brucia la carne. Eludere la sua rete è impossibile.', name_es = 'Tejedor de llama', description_es = 'Envuelto en llamas de absolución, el arco de la Viuda Errante atraviesa el corazón y abrasa la carne. Nadie escapará de su red de deseo.' WHERE name_en = 'Weaver of Flame' AND type = 'bow';
UPDATE equipment SET name_ja = 'かんなりの神弓', description_ja = '美雅なる雷神龍、強弓となりて浮世に顕現。 放たれし矢は、界雷となって獲物を射抜く。', name_fr = 'Arc du tonnerre', description_fr = 'La rage de la Narwa sous la forme d''un arc. Foudroie ses victimes sans pitié.', name_it = 'Arco saetta', description_it = 'La furia della Narwa si scatena sul cosmo. Colpisce con la forza del fulmine.', name_es = 'Arco Relámpago', description_es = 'La furia de Narwa en el plano mortal. Atraviesa enemigos como el rayo.' WHERE name_en = 'Thunderbolt Bow' AND type = 'bow';
UPDATE equipment SET name_ja = '六花晶弓', description_ja = '結晶を纏った弓。美しき氷の花に目を奪われれば最後、 放たれた矢に命を射抜かれる。', name_fr = 'Fleur cristalline', description_fr = 'Arc incrusté de cristal. La mort est imminente pour ceux qui admirent ses flèches.', name_it = 'Fiore cristallino', description_it = 'Arco ricoperto di cristalli. La filigrana glaciale delle frecce sorprende il nemico.', name_es = 'Flor cristalina', description_es = 'Arco con incrustaciones de cristal y temibles flechas de gélida filigrana.' WHERE name_en = 'Crystalline Flower' AND type = 'bow';
UPDATE equipment SET name_ja = 'ネコ弐九弓', description_ja = 'アイルーの頭に似せた愛らしさ満点の弓。 くわっと口を開けて威嚇をすれば、攻撃の合図！', name_fr = 'Arc Felyne', description_fr = 'Arc très mignon en forme de tête de Felyne qui ouvre sa gueule à chaque tir.', name_it = 'Arco Felyne', description_it = 'Simpatico arco a forma di testa di Felyne. La bocca si apre per scoccare la freccia.', name_es = 'Arco de Felyne', description_es = 'Arco monísimo con forma de cabeza de Felyne. Lanza flechas por la boca.' WHERE name_en = 'Felyne Bow' AND type = 'bow';
UPDATE equipment SET name_ja = '青熊弓', description_ja = '青熊獣の色鮮やかな体毛で彩られた大弓。 番えた矢からは仄かに蜜の香りがする。', name_fr = 'Arc Arzuros', description_fr = 'Arc à la parure semblable à la fourrure éclatante d''un Arzuros. Son odeur évoque le miel.', name_it = 'Arco Arzuros', description_it = 'Granarco con pelo di Arzuros che emana un delicato profumo di miele.', name_es = 'Arco Arzuros', description_es = 'Gran arco con el distintivo pelaje moteado de un Arzuros. Huele a miel.' WHERE name_en = 'Arzuros Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'スポンギア', description_ja = 'ロアルドロスの素材で作られた弓。 弦を引けば水分があふれ出し、矢じりを厚く包み込む。', name_fr = 'Arc-éponge', description_fr = 'Fait de matériaux de Ludroth royal. Quand on tire sur sa corde, de l''eau jaillit et vient envelopper la flèche.', name_it = 'Arco spugnoso', description_it = 'Arco realizzato con parti di Ludroth reale. Quando si tende la corda, fuoriesce un getto d''acqua che circonda la freccia.', name_es = 'Arco esponja', description_es = 'Hecho con materiales sacados del Ludroth Real. Al tensarse la cuerda, empapa la flecha con agua.' WHERE name_en = 'Spongia Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'ダークフィラメント', description_ja = '禍々しき紅炎を身に宿す剛弓。 矢は業火となりて対象を滅す。', name_fr = 'Filament noir', description_fr = 'Arc qui renferme un feu vivace en son cœur. Ses flèches plongent leurs proies en enfer.', name_it = 'Filamento oscuro', description_it = 'Un arco con fiamme rosse nel suo fulcro. Le frecce scoccate incendiano i bersagli.', name_es = 'Filamento oscuro', description_es = 'Arco que alberga ardientes llamas rojas en su núcleo. Sus flechas envuelven al rival en fuego infernal.' WHERE name_en = 'Dark Filament' AND type = 'bow';
UPDATE equipment SET name_ja = '王弓エンライ', description_ja = '世に名高き無双の王者の甲殻を用いた弓。 解き放たれた王の牙は獲物の急所を正確に射貫く。', name_fr = 'Tonnerre du tyran', description_fr = 'Arc en carapace de monarque hors pair. Ses flèches tailladent les ennemis.', name_it = 'Rombo del tiranno', description_it = 'Arco realizzato dalla corazza di un monarca ineguagliato. Le sue frecce trafiggono i nemici come zanne.', name_es = 'Retumbar usurpador', description_es = 'Arco hecho con la coraza de un rey sin par. Sus flechas diezman a los enemigos.' WHERE name_en = 'Usurper''s Rumble' AND type = 'bow';
UPDATE equipment SET name_ja = 'ティガアロー', description_ja = '轟竜の素材で作られた弓。 荒ぶるティガレックスの一撃は、岩をも貫く。', name_fr = 'Arc Tigrex', description_fr = 'Fait à partir d''un Tigrex et imprégné d''assez de rage pour détruire des rochers.', name_it = 'Arco Tigrex', description_it = 'Arco realizzato con parti di Tigrex e intriso di una rabbia tale da spaccare la roccia.', name_es = 'Arquero Tigrex', description_es = 'Hecho con materiales sacados del Tigrex e impregnado con suficiente ira como para reventar las rocas.' WHERE name_en = 'Tigrex Archer' AND type = 'bow';
UPDATE equipment SET name_ja = 'ブルーブレイドボウ', description_ja = '鋭角的な意匠の施された猟弓。 無属性ながら研ぎ澄まされた矢は、硬い鱗をも易々と徹す。', name_fr = 'Arc lame bleue', description_fr = 'Arc parfaitement courbé. Permet de tirer facilement des flèches non élémentaires.', name_it = 'Arco lama blu', description_it = 'Un arco dalla curva accentuata, pensato per scagliare facilmente frecce non elementali.', name_es = 'Arco de hoja azul', description_es = 'Arco de ángulo pronunciado. Hace fácil disparar dardos no elementales.' WHERE name_en = 'Blue Blade Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'ライトニングボウ', description_ja = '硬い甲殻を裂き、肉を射抜く、疾雷の如き矢を放つ勁弓。 脅威の技術の結晶。', name_fr = 'Arc d''orage', description_fr = 'Petit bijou de technologie pouvant transpercer à la fois carapace et chair.', name_it = 'Arco fulmine', description_it = 'Le frecce di questo prodigio tecnologico possono squarciare carni e corazze.', name_es = 'Arco de relámpago', description_es = 'Una maravilla tecnológica. Sus flechas perforan carne y caparazones por igual.' WHERE name_en = 'Lightning Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'デュークフレーダー', description_ja = 'コウモリのような形状が特徴の爵銀龍の弓。 その矢は一陣の風となり、闇夜を切り裂く。', name_fr = 'Ailes de sang du Duc', description_fr = 'Arc Malzeno en forme de chauve-souris. Ses flèches transpercent la nuit comme le vent.', name_it = 'Arco ducale', description_it = 'Arco di Malzeno a forma di pipistrello. Le sue frecce squarciano la notte.', name_es = 'Alasangre ducal', description_es = 'Arco de Malzeno en forma de murciélago que perfora como el viento la noche estrellada.' WHERE name_en = 'Duke''s Bloodwings' AND type = 'bow';
UPDATE equipment SET name_ja = 'ゴルム・ボーゲン', description_ja = '剛纏獣の硬い素材を使った弓。 盾のように分厚い弓は、殴り付けるような強烈な矢を放つ。', name_fr = 'Arc Os Golm', description_fr = 'Gros arc robuste en Garangolm lançant des flèches comme des javelots.', name_it = 'Arco osseo Garangolm', description_it = 'Arco simile a uno scudo in parti resistenti di Garangolm. Lancia frecce come fossero giavellotti.', name_es = 'Arco hueso Garangolm', description_es = 'Voluminoso arco de Garangolm tan robusto que parece un escudo. Lanza las flechas como si fueran jabalinas.' WHERE name_en = 'Golm Bone Bow' AND type = 'bow';
UPDATE equipment SET name_ja = 'アイスライザー', description_ja = 'イヴェルカーナの素材を用いて作られた弓。 極寒の一矢は苦痛に呻く声すら即座に凍結させ、永遠の静寂を与える。', name_fr = 'Lanceur de glace', description_fr = 'Arc de glace créé à partir de matériaux de Velkhana qui étouffe les cris de sa proie dans sa gorge.', name_it = 'Criocatapulta', description_it = 'L''arco ghiacciato di Velkhana rabbrividisce e congela l''ultimo grido nella gola della preda.', name_es = 'Lanzador de hielo', description_es = 'Arco gélido hecho con elementos del Velkhana. Congela en el aire los últimos gritos de su presa.' WHERE name_en = 'Iceflinger' AND type = 'bow';
UPDATE equipment SET name_ja = '龍頭琴', description_ja = '加護の祈りが込められた竪琴。 竜人族の楽士は旅する時、これで身を守ったという。', name_fr = 'Harpe hippocampe', description_fr = 'Arc divin des ménestrels wyvériens. Pour tuer et parfois faire de la musique.', name_it = 'Arpa marina', description_it = 'Arco divino usato dai menestrelli wyveriani, usato sia per la guerra che pizzicato per suonare qualche canzone.', name_es = 'Arpa caballito mar', description_es = 'Arco divino. Los juglares wyverianos lo usan para luchar y tocar alguna que otra melodía.' WHERE name_en = 'Seahorse Harp' AND type = 'bow';
UPDATE equipment SET name_ja = 'ユミ【烏】', description_ja = '毒の性質を持つ、イャンガルルガから作られた弓。 黒狼鳥の魂が毒矢となり、獲物を蝕む。', name_fr = 'Arc corbeau', description_fr = 'Créé à base de matériaux de Yian Garuga. Prêtes à dévorer leurs proies, les flèches sont imbibées du venin du monstre.', name_it = 'Arco corvo', description_it = 'Realizzato con parti di Yian Garuga. Le frecce sono intrise del suo veleno, attendendo impazientemente di colpire la preda.', name_es = 'Arco de cuervo', description_es = 'Hecho con partes de Yian Garuga. El veneno del monstruo sigue activo en sus flechas, listo para consumir a la presa.' WHERE name_en = 'Crow Bow' AND type = 'bow';
UPDATE equipment SET name_ja = '鳥幣弓', description_ja = 'イャンクックの素材を使った火を放つ猟弓。 扱い易さに定評がある。', name_fr = 'Arc Kut-Ku', description_fr = 'Arc Yian Kut-Ku tirant des flèches de feu, réputé facile d''utilisation.', name_it = 'Arco Kut-Ku', description_it = 'Arco da caccia ricavato da parti di Yian Kut-Ku. Scaglia proiettili infuocati e tutti dicono che sia molto maneggevole.', name_es = 'Arco Kut-Ku', description_es = 'Arco de caza de Yian Kut-Ku que dispara saetas de fuego y tiene fama de ser fácil de manejar.' WHERE name_en = 'Kut-Ku Stave' AND type = 'bow';
UPDATE equipment SET name_ja = '６４式連装弓', description_ja = '工匠団が総力を挙げて設計した対飛竜用弓。 最新鋭の技術が惜しみなくつぎ込まれている。', name_fr = 'Multi-arc T-64', description_fr = 'Arc de pointe pour battre les wyvernes volantes. Les artisans ont beaucoup investi pour son développement.', name_it = 'Multiarco T-64', description_it = 'Arco progettato per uccidere i wyvern volanti, nel cui sviluppo gli artigiani hanno investito molto tempo e denaro.', name_es = 'Multiarco tipo 64', description_es = 'Arco avanzado diseñado para luchar contra wyverns voladores con la financiación del gremio.' WHERE name_en = 'Type 64 Multibow' AND type = 'bow';
UPDATE equipment SET name_ja = '灼炎のヴァルスター', description_ja = '広がる炎を表現した弓が、壮絶な火の雨を降らす。 弾け、その弓の名は灼炎のヴァルスター。', name_fr = 'Colère de cendre', description_fr = 'Arc venu de l''enfer, qui fait pleuvoir un véritable déluge de feu sur l''ennemi.', name_it = 'Valstella cinerea', description_it = 'Arco infernale che tartassa i nemici con frecce fiammeggianti senza mostrare alcuna pietà.', name_es = 'Ira de ceniza', description_es = 'Arco que encarna un infierno y lanza flechas llameantes a sus enemigos sin remordimientos.' WHERE name_en = 'Ashen Wrath' AND type = 'bow';
UPDATE equipment SET name_ja = '龍弓【日輪】', description_ja = 'ヤマツカミの背に生えた龍木から削り出された神秘的な弓。 加工の技法は口伝でのみ残る。', name_fr = 'Arc dragon solaire', description_fr = 'Arc mystique taillé dans le bois-dragon de Yama Tsukami. Le secret de sa fabrication n''est transmis que de bouche à oreille.', name_it = 'Arco-drago Solare', description_it = 'Arco mistico intagliato dal legno di drago che cresce sugli Yama Tsukami. Il modo per produrlo viene tramandato solo oralmente.', name_es = 'Arco dragón Sol', description_es = 'Arco mítico tallado con la madera de dragón que crece sobre el Yama Tsukami. Su técnica de tallado solo se lega mediante tradición oral.' WHERE name_en = 'Dragon Bow Solar' AND type = 'bow';
UPDATE equipment SET name_ja = 'アルシュアルクム', description_ja = 'アルシュベルドの素材で作られた弓。放たれた矢は まるで射手の意思に導かれるように竜の急所を射抜く。', name_fr = 'Arcum Arkveld', description_fr = 'Arc fabriqué avec des matériaux d''Arkveld. Ses flèches trouvent les organes vitaux, comme guidées par la volonté de l''archer.', name_it = 'Arcum Veldian', description_it = 'Un arco realizzato con materiali di Arkveld. Le sue frecce trovano gli organi dei wyvern come se ascoltassero chi lo impugna.', name_es = 'Arcum veldiano', description_es = 'Arco hecho de materiales de Arkveld. Encuentra y perfora los puntos vitales como si respondiese a la voluntad de su dueño.' WHERE name_en = 'Veldian Arcum' AND type = 'bow';
UPDATE equipment SET name_ja = 'レ・ペルコンス', description_ja = 'レ・ダウの雷を纏いし弓。 幾千の雷撃を放ってもなお、矢に伝わる力は衰えない。', name_fr = 'Rey Perkonis', description_fr = 'Arc imprégné de la foudre du Rey Dau. Garde sa puissance électrique même après avoir tiré un millier d''éclairs.', name_it = 'Perkonis Rey', description_it = 'Un arco infuso del tuono di Rey Dau che mantiene la carica anche dopo aver scagliato migliaia di saette.', name_es = 'Rey Perkonis', description_es = 'Arco imbuido con la energía del rayo del Rey Dau, capaz de retener su carga incluso después de soltar mil descargas.' WHERE name_en = 'Rey Perkonis' AND type = 'bow';
UPDATE equipment SET name_ja = 'アルクセロジョーヌ', description_ja = '飛甲虫の素材で作られた美しい弓。 獲物を内部から焼き焦がす雷属性を備えている。', name_fr = 'Arko Nulo jaune', description_fr = 'Arc élégant en Bnahabra. Ses flèches foudroyantes sont du tonnerre !', name_it = 'Arco Nulo giallo', description_it = 'Elegante arco fatto di parti di Bnahabra. Le sue proprietà elettriche generano shock e stupore.', name_es = 'Arko Nulo amarillo', description_es = 'Elegante arco de Bnahabra con sobrecogedoras propiedades eléctricas.' WHERE name_en = 'Arko Nulo Yellow' AND type = 'bow';
UPDATE equipment SET name_ja = 'アルクセロルージュ', description_ja = '飛甲虫の素材で作られた美しい弓。 獲物を燃え上がらせる火属性を備えている。', name_fr = 'Arko Nulo rouge', description_fr = 'Arc élégant en Bnahabra. Ses flèches peuvent brûler ses proies.', name_it = 'Arco Nulo rosso', description_it = 'Arco elegante con parti di Bnahabra. Scaglia frecce che possono incenerire i nemici.', name_es = 'Arko Nulo rojo', description_es = 'Elegante arco de partes de Bnahabra. Sus flechas incineran a las presas.' WHERE name_en = 'Arko Nulo Red' AND type = 'bow';
