UPDATE equipment SET name_ja = 'アルクセロノワール', description_ja = '飛甲虫の素材で作られた美しい弓。 携える者に、龍を退ける力を授けるといわれる。', name_fr = 'Arko Nulo noir', description_fr = 'Arc d''ébène en Bnahabra à l''air solennel. Sert à vaincre les dragons.', name_it = 'Arco Nulo nero', description_it = 'Arco d''ebano solenne di Bnahabra che aiuta ad annientare i draghi.', name_es = 'Arko Nulo negro', description_es = 'Solemne arco de ébano de Bnahabra que hace fácil matar dragones.' WHERE name_en = 'Arko Nulo Black' AND type = 'bow';
UPDATE equipment SET name_ja = 'プリンセスバースト', description_ja = '女王の美しき濃緑の鱗に抱かれた華麗なる銃槍。 猛毒に沈む命は続く砲撃に紅く美しく咲く。', name_fr = 'Panoplie princesse', description_fr = 'Lancecanon en écailles vertes de la Reine. Tirant du poison, il souille la terre du sang des ennemis.', name_it = 'Sfarzo principesco', description_it = 'Lancia-fucile con scaglie della regina che lancia colpi avvelenati e macchia la terra con il sangue dei nemici.', name_es = 'Panoplia de princesa', description_es = 'Lanza pistola cubierta de las verdes escamas de la reina. Dispara proyectiles venenosos, marcando la tierra con la sangre de sus víctimas.' WHERE name_en = 'Princess Panoply' AND type = 'gunlance';
UPDATE equipment SET name_ja = '飛雷銃槍テツカガチ', description_ja = '飛雷竜の鱗から造られた銃槍。 砲身から放たれた一撃は電流をまとい、獲物へと襲いかかる。', name_fr = 'Destructeur Kadachi', description_fr = 'Lancecanon en écailles de Tobi-Kadachi. Envoie une décharge électrique à chacun de ses impacts.', name_it = 'Percussore Kadachi I', description_it = 'Realizzata con pelle di Tobi-Kadachi. Ogni colpo di questa lancia-fucile genera una scossa elettrica letale.', name_es = 'Asalto Kadachi', description_es = 'Hecha con escamas de Tobi-Kadachi. Cada impacto de esta lanza pistola canaliza una carga eléctrica hacia tu presa.' WHERE name_en = 'Kadachi Striker' AND type = 'gunlance';
UPDATE equipment SET name_ja = '愚欲の銃槍', description_ja = '激憤する恐ろしき王を封じた、恐暴竜の銃槍。 その封印が破れる時、世界は終焉の時を迎える。', name_fr = 'Lancecanon vorace', description_fr = 'Lancecanon où est emprisonné le terrible Deviljho. Si le sceau est brisé, le monde court à sa perte.', name_it = 'Lancia-fucile vorace', description_it = 'Lancia-fucile che contiene il terribile Deviljho. Se il sigillo dovesse rompersi, sarebbe la fine di questo mondo.', name_es = 'Lanza pistola voraz', description_es = 'Lanza pistola que encierra al temible Deviljho. Si un día el sello se desata, será el fin del mundo.' WHERE name_en = 'Ravenous Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'デュアルトゥース', description_ja = '氷牙竜の二本の牙から造られた銃槍。 その一撃は吹き荒れる吹雪の如く獲物を翻弄する。', name_fr = 'Double peine', description_fr = 'Lancecanon fait avec deux crocs glacés de Barrioth. Aussi rude qu''un blizzard.', name_it = 'Gemelzanna', description_it = 'Lancia-fucile ricavata dalle zanne gelate di un Barioth. Colpisce come una bufera.', name_es = 'Colmillo doble', description_es = 'Lanza pistola hecha con los colmillos de un Barioth. Azota a sus presas con una ventisca helada.' WHERE name_en = 'Twinfang' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ティガバースト', description_ja = '轟竜の素材を用いた銃槍。 咆哮の如き砲撃は、飛竜すらも恐怖を覚える。', name_fr = 'Explosion Rex', description_fr = 'Lancecanon à base de Tigrex. Son rugissement fait même fuir les wyvernes.', name_it = 'Soffio di Rex', description_it = 'Lancia-fucile di Tigrex. Il suo ruggito semina il panico tra i wyvern.', name_es = 'Explosión Rex', description_es = 'Lanza pistola hecha de partes de Tigrex. Su rugido hace huir a los wyverns.' WHERE name_en = 'Tiger Blast' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ヒドラ・エフィーラ', description_ja = 'ネロミェールの銃槍。刃は底の見えぬ暗闇。 明滅する光も出口なき深淵への道標に過ぎない。', name_fr = 'Éphyra hydra', description_fr = 'Lancecanon Namielle. Les ténèbres éternelles guident sa proie vers l''abysse.', name_it = 'Efira di Idra', description_it = 'L''eterna oscurità danza sulla lancia-fucile di Namielle, attirando la preda nell''abisso.', name_es = 'Ephyra Hidra', description_es = 'Una oscuridad sin fin baila en esta lanza pistola de Namielle, llevando a sus presas al abismo.' WHERE name_en = 'Hydra Ephyra' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'アイアンガンランス', description_ja = '鉄で作られたオーソドックスなガンランス。  状況に合わせ銃と槍を使い分けることができる。', name_fr = 'Lancecanon de fer', description_fr = 'Lancecanon en fer standard qui laisse le choix entre coups de feu et attaques de mêlée.', name_it = 'Lancia-fucile ferro', description_it = 'Comune lancia-fucile di ferro ideale sia per sparare, sia per eseguire attacchi in mischia.', name_es = 'Lanza pistola hierro', description_es = 'Lanza pistola de hierro corriente que te permite elegir entre disparos y ataques cuerpo a cuerpo' WHERE name_en = 'Iron Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ディオスガンランス', description_ja = '蔵した粘菌が発光する銃槍。 砕竜の力を生かした砲撃機構は人智を超えた破壊力を生む。', name_fr = 'Lancecanon Dios', description_fr = 'Lancecanon enduit de poisse de Brachydios luisante. Son pouvoir est surnaturel.', name_it = 'Lancia-fucile Dios', description_it = 'Lancia-fucile riempita con lucente melma di Brachydios. Il suo potere va oltre l''umana scienza.', name_es = 'Lanza pistola Brach', description_es = 'Lanza pistola con limo brillante de Brachydios. Su poder es inconmensurable.' WHERE name_en = 'Dios Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'シルムズガリング', description_ja = '各所にあしらわれた意匠が雅な傘鳥の銃槍。 最新鋭の排熱機関が常に温度を調整している。', name_fr = 'Lancecanon Aknosom', description_fr = 'Lancecanon élégant en Aknosom. Possède un système de refroidissement avancé.', name_it = 'Lancia-fucile Aknosom', description_it = 'Elegante lancia-fucile con parti di Aknosom e un ottimo sistema di raffreddamento.', name_es = 'Lanza pistola Aknosom', description_es = 'Elegante lanza pistola hecha de partes de Aknosom. Tiene un avanzado sistema de refrigeración.' WHERE name_en = 'Aknosom Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = '禍ツ砲槍【封】', description_ja = 'その銃槍は、怨虎竜の咆哮が如く、幾百の竜をも打ち払う。 深き怨念を内に秘めたままで。', name_fr = 'Lancecanon sinistre', description_fr = 'Le son de cette arme évoque le rugissement de la Wyverne maléfique.', name_it = 'Lancia-fucile sinistra', description_it = 'Questa lancia-fucile ruggisce come il wyvern della malvagità.', name_es = 'Lanza pistola siniestra', description_es = 'El sonido de esta lanza pistola recuerda al rugido del wyvern malicioso.' WHERE name_en = 'Sinister Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'Ｄ＝ネイ', description_ja = '甲殻を活用した泥翁竜の銃槍。 特殊な金属が、泥濘の地でも安定した機動を生むという。', name_fr = 'Lancecanon Almudron', description_fr = 'Arme faite en Almudron. Elle se manie à merveille, même dans la boue.', name_it = 'Lancia-fucile Almudron', description_it = 'Lancia-fucile con parti di Almudron. Stabile persino sul terreno più fangoso.', name_es = 'Lanza pistola Almudron', description_es = 'Lanza pistola hecha de partes de Almudron. De manejo fácil incluso sobre el barro.' WHERE name_en = 'Almudron Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = '砲モロコシ', description_ja = '農業に対する強き想いが銃槍へと昇華した。 美味しそうな見かけによらず、圧倒的な砲撃威力を秘める。', name_fr = 'Canon à maïs', description_fr = 'Conçu par un artisan qui rêvait peut-être d''être agriculteur. Plus puissant qu''il n''en a l''air.', name_it = 'Mietitrice', description_it = 'Progettata da un artigiano che forse sognava di diventare contadino. Più potente di quanto sembri.', name_es = 'Maicera', description_es = 'Diseñada por un artesano que quizá soñara con ser granjero. Es más poderosa de lo que aparenta.' WHERE name_en = 'Cornpopper' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'フィオレセロベルデ', description_ja = '飛甲虫の素材が目にも鮮やかなガンランス。 棘の如き先端には麻痺毒が仕込まれている。', name_fr = 'Fiore Nulo vert', description_fr = 'Lancecanon Bnahabra dont la pointe acérée de peut paralyser en un seul coup.', name_it = 'Fiore Nulo verde', description_it = 'Lancia-fucile di Bnahabra in grado di paralizzare con un singolo colpo della sua punta fine.', name_es = 'Fiore Nulo verde', description_es = 'Un solo golpe de la punta en forma de espina de esta lanza pistola de Bnahabra causa parálisis.' WHERE name_en = 'Fiore Nulo Green' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'フィオレセロルージュ', description_ja = '飛甲虫の素材が目にも鮮やかなガンランス。 燃え立つような赤い砲身は花の蕾を思わせる。', name_fr = 'Fiore Nulo rouge', description_fr = 'Lancecanon Bnahabra dont le canon écarlate évoque un bourgeon de fleurs.', name_it = 'Fiore Nulo rosso', description_it = 'La canna granata di questa lancia-fucile di Bnahabra richiama alla mente boccioli di fiori.', name_es = 'Fiore Nulo rojo', description_es = 'El cañón marrón de esta lanza pistola de Bnahabra recuerda a brotes de flores.' WHERE name_en = 'Fiore Nulo Red' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'フィオレセロノワール', description_ja = '飛甲虫の素材が目にも鮮やかなガンランス。 龍討ちの力が秘められている。', name_fr = 'Fiore Nulo noir', description_fr = 'Lancecanon noir en Bnahabra conçu pour être efficace contre les dragons.', name_it = 'Fiore Nulo nero', description_it = 'Questa lancia-fucile nera di Bnahabra è particolarmente efficace contro i draghi.', name_es = 'Fiore Nulo negro', description_es = 'Lanza pistola negra que fue diseñada especialmente para enfrentarse a dragones.' WHERE name_en = 'Fiore Nulo Black' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ドロスハープーン', description_ja = '漁で用いられる銛に着想を得て狩猟用武器に改造した銃槍。 抜刀時に先端の槍が露出する。', name_fr = 'Harpon Ludroth', description_fr = 'Matériel de pêche modifié pour servir à chasser. Pointe rétractable.', name_it = 'Arpione Ludroth', description_it = 'Utensile da pesca modificato per la caccia. La punta fuoriesce per l''attacco.', name_es = 'Arpón Ludroth', description_es = 'Herramienta de pesca rediseñada para cazar monstruos. La punta se expone durante el combate.' WHERE name_en = 'Ludroth Harpoon' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ボルボローダー', description_ja = '圧倒的な強度と砲撃を誇る、土砂竜の銃槍。 その耐久力は、泥土を纏うボルボロスそのもの。', name_fr = 'Chargeur Barroth', description_fr = 'Possède une extraordinaire puissance de feu et de mêlée. Sa robustesse égale celle de la peau rocailleuse d''un Barroth.', name_it = 'Caricatore Barroth', description_it = 'Lancia-fucile ideale per lanciare fiamme e attaccare in mischia, robusta quasi quanto la corazza di Barroth.', name_es = 'Cargador Barroth', description_es = 'Presume de un abrumador poder de disparo y de ataque cuerpo a cuerpo. Es tan compacta como la pétrea piel del Barroth.' WHERE name_en = 'Barroth Loader' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ヒルバーガンランス', description_ja = '毒妖鳥素材で造った銃槍。 盾は風景に紛れやすい色になっており、身を隠すのに役立つ。', name_fr = 'Lancecanon Pukei', description_fr = 'Lancecanon en Pukei-Pukei assorti d''un bouclier pour se fondre dans le décor.', name_it = 'Lancia-fucile Pukei', description_it = 'Lancia-fucile in parti di Pukei-Pukei, munita di scudo con colori mimetici.', name_es = 'Lanza pistola Pukei', description_es = 'Lanza pistola hecha de partes de Pukei-Pukei. Tiene un escudo con colores de camuflaje.' WHERE name_en = 'Pukei Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = '王銃槍ゴウライ', description_ja = '無双の王者の力を封じた銃槍。 轟く咆哮は真の支配者たる王の出現を世に知らしめる。', name_fr = 'Hurlement du tyran', description_fr = 'Lancecanon au pouvoir d''un monarque. Annonce la venue du grand conquérant.', name_it = 'Ruggito del tiranno', description_it = 'Lancia-fucile dal potere di un monarca, che annuncia l''arrivo del conquistatore.', name_es = 'Rugido del usurpador', description_es = 'Lanza pistola con el poder de un monarca. Su poderoso rugido anuncia la conquista.' WHERE name_en = 'Usurper''s Roar' AND type = 'gunlance';
UPDATE equipment SET name_ja = '冷たき月の銃槍', description_ja = '砲身を氷が覆う氷狼竜の銃槍。 砲撃を行うたびに弾けた氷片が月明かりに照らされて輝く。', name_fr = 'Lancecanon de la lunegivre', description_fr = 'Lancecanon Lunagaron dont le canon gelé disperse à chaque tir des éclats de glace scintillants.', name_it = 'Lancia-fucile lunafredda', description_it = 'La canna gelida di questa lancia-fucile di Lunagaron emette schegge di ghiaccio illuminate dalla luna a ogni colpo.', name_es = 'Lanza pistola del relente', description_es = 'El cañón congelado de esta Lanza pistola de Lunagaron dispersa fragmentos de hielo iluminados por la luna con cada disparo.' WHERE name_en = 'Frostmoon Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ローゼンカノーネ', description_ja = '棘竜の素材を用いた銃槍。 その「砲撃」は、領域を侵す全てを吹き飛ばす。', name_fr = 'Rosenkanone', description_fr = 'Lancecanon Espinas. Son "rugissement" repousse tout ce qui se trouve à sa portée.', name_it = 'Rosenkanone', description_it = 'Lancia-fucile Espinas. Il suo fiero ruggito spazza via qualsiasi invasore.', name_es = 'Rosenkanone', description_es = 'Lanza pistola de Espinas, cuyo feroz rugido elimina a quien se adentre en su territorio.' WHERE name_en = 'Rosenkanone' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'かまくランス', description_ja = 'アイルー達の力作がモチーフ。 雪解けの日、気落ちする彼らにプレゼントされた工房の快作。', name_fr = 'Lancecanon Kamak', description_fr = 'Œuvre d''art destinée aux Felynes qui voudraient que l''hiver dure toujours.', name_it = 'Lancia-fucile Kamak', description_it = 'Elegante opera d''arte per i Felyne depressi per la fine dell''inverno.', name_es = 'Lanza pistola Kamak', description_es = 'Excelente obra de arte creada por Felynes desencantados con la llegada del fin del invierno.' WHERE name_en = 'Kamak Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'マリンフィッシャー', description_ja = '鋭い先端から水流が噴き出す、ガノトトスのガンランス。 水に呑みこまれた獲物は、霞んだ視界のなか最期を迎える。', name_fr = 'Pêcheur marin', description_fr = 'Lancecanon de Plesioth à dents pointues qui envoie des jets d''eau pour aveugler sa proie avant de l''achever.', name_it = 'Pescatore marino', description_it = 'Affilata lancia-fucile di Plesioth che spara getti d’acqua accecando la preda, ormai vicina alla sua fine.', name_es = 'Pescador marino', description_es = 'Lanza pistola puntiaguda de Plesioth que dispara chorros de agua, cegando así a la presa y condenándola a la perdición.' WHERE name_en = 'Marine Fisher' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ホワイトガンランス', description_ja = '鎧竜の甲殻を槍身と盾に使用した、グラビモスのガンランス。 その大きさは、抜群の存在感を漂わせる。', name_fr = 'Lancecanon blanc', description_fr = 'Lance et bouclier tous deux à base d''écailles de Gravios. Leur taille remarquable attire l''œil.', name_it = 'Lancia-fucile bianca', description_it = 'Sia la lancia che lo scudo sono realizzati con scaglie di Gravios. Le grandi dimensioni attirano subito l''attenzione.', name_es = 'Lanza pistola blanca', description_es = 'Tanto la lanza como el escudo están forjados con escamas de Gravios. Su gran tamaño salta a la vista.' WHERE name_en = 'White Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ハードヒッター', description_ja = 'ゲリョスの皮膚と、良質な鉱石を組み合わせた銃槍。 その毒液に獲物は壮絶な苦痛を味わった末、息絶える。', name_fr = 'Frappeur dur', description_fr = 'Créé à base de plumes de Gypceros et de minerai affiné. Contient un venin létal qui fait agoniser ses cibles.', name_it = 'Percussore duro', description_it = 'Realizzato in pelle di Gypceros e minerali pregiati. Il suo veleno letale non lascia scampo alle sfortunate prede.', name_es = 'Golpeadora dura', description_es = 'Hecha de cuero de Gypceros y minerales finos. Contiene un veneno letal que causa inmensa agonía a sus desafortunadas víctimas.' WHERE name_en = 'Hard Hitter' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ヘルスティング', description_ja = '凄まじい凍気を放つ雪獅子の素材を使い、 高い冷却機能を備えたガンランス。', name_fr = 'Dardenfer', description_fr = 'Lancecanon en Blangonga, qui jette un froid chez l''adversaire.', name_it = 'Aculeo infernale', description_it = 'Lancia-fucile che sferra colpi gelidi grazie alle parti di Blangonga.', name_es = 'Punzada del infierno', description_es = 'Lanza pistola capaz de producir un frío severo con la ayuda de sus restos de Blangonga.' WHERE name_en = 'Hellsting' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'シェルガンバード', description_ja = '影蜘蛛の素材を曲線的に重ね合わせた銃槍。 一見華奢に見えるが、その姿の強度は計り知れない。', name_fr = 'Avicanon', description_fr = 'Créé à partir de matériaux de Nerscylla superposés. Son apparence fragile dissimule sa vraie force.', name_it = 'Aviofucile guscio', description_it = 'Realizzato con parti di Nerscylla. Fragile all''apparenza, nasconde un grande potere.', name_es = 'Rapaz acorazada', description_es = 'Hecha de capas de partes de Nerscylla. Su frágil apariencia esconde su verdadero poder.' WHERE name_en = 'Shell Gunbird' AND type = 'gunlance';
UPDATE equipment SET name_ja = '６２式突撃銃槍', description_ja = '工匠団の機密技術がつぎ込まれた対飛竜用銃槍。 竜を屠る事だけに特化した恐るべき兵器。', name_fr = 'Oragelance T-62', description_fr = 'Redoutable lancecanon forgé avec une technologie secrète artisanale. Conçu pour tuer les wyvernes.', name_it = 'Lanciabufera T-62', description_it = 'Temibile lancia-fucile creata con tecniche segrete della Gilda e ideata per uccidere i wyvern.', name_es = 'Lanzatormenta tipo 62', description_es = 'Temible lanza pistola hecha con tecnología artesanal de alto secreto. Muy efectiva contra wyverns.' WHERE name_en = 'Type 62 Stormlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = '龍木ノ槍【金剛】', description_ja = '龍木を加工し作られた、竜人族秘伝の銃槍。 構造上、中折れ式ではない。', name_fr = 'Lancecanon bois-dragon doré', description_fr = 'Fait de bois-dragon via une méthode wyvérienne secrète. Il ne se replie pas quand il est porté sur le dos.', name_it = 'Lanc.-fuc. in legno di drago dorata', description_it = 'Fatta di legno di drago con metodi wyverniani segreti. Grazie al suo design, non si piega quando viene portata sulla schiena.', name_es = 'Lanza pistola madera de dragón dorada', description_es = 'Lanza pistola hecha de madera de dragón mediante métodos wyverianos. Debido a su diseño, no se pliega al colocarla a la espalda.' WHERE name_en = 'Gold Dragonwood Gunlance' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'レッドジェネレーター', description_ja = '電撃袋により属性を強化したフルフル亜種の銃槍。 フルフルベースながら、メカニカルな見た目が特徴。', name_fr = 'Générateur rouge', description_fr = 'Lancecanon équipé d''un générateur puissant. Son origine Khezu est discrète.', name_it = 'Generatore rosso', description_it = 'Lancia-fucile con un potente serbatoio elettrico. Non sembra un''arma Khezu.', name_es = 'Generador rojo', description_es = 'Lanza pistola con una gran reserva eléctrica. No recuerda al Khezu con el que fue hecha.' WHERE name_en = 'Red Generator' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'ラギアバースト', description_ja = '渦巻くような形状が特徴的な、海竜の銃槍。 放たれる爆雷は螺旋を描き、獲物に電流を流し込む。', name_fr = 'Explosif Lagia', description_fr = 'Distordu comme un tourbillon, ce lancecanon de Lagiacrus lance des charges électriques qui fondent sur leur proie.', name_it = 'Scoppio Lagiacrus', description_it = 'La vorticosa lancia-fucile di Lagiacrus rilascia scariche elettriche che avvolgono la preda.', name_es = 'Estallido de Lagia', description_es = 'Retorcida como un torbellino, la lanza pistola Lagiacrus desata descargas eléctricas que rodean a la presa en una espiral.' WHERE name_en = 'Lagia Burst' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'アルシュアスタ', description_ja = 'アルシュベルドの素材で作られた銃槍。 平和を誓う騎士は、生きるものを見下す傲慢な竜を地に下した。', name_fr = 'Arkhastae', description_fr = 'Lancecanon fabriqué avec des matériaux d''Arkveld. Il a permis de rendre à la terre une wyverne arrogante qui avait défié la nature.', name_it = 'Asta Veldian', description_it = 'Una lancia-fucile realizzata con materiali di Arkveld. Grazie a essa, un wyvern altero rivoltatosi contro la natura fu restituito alla terra.', name_es = 'Asta veldiana', description_es = 'Lanza pistola de materiales de Arkveld. Sirvió para ponerle las patas en la tierra a un orgulloso wyvern que osó revelarse contra la naturaleza.' WHERE name_en = 'Veldian Hasta' AND type = 'gunlance';
UPDATE equipment SET name_ja = '赫炎の銃槍', description_ja = 'アジャラカンの力を秘めし銃槍。 高出力で噴出される炎熱をもって眼前の障害を瞬時に払い除ける。', name_fr = 'Piquestolet Ajara', description_fr = 'Lancecanon Ajarakan produisant de puissantes rafales de chaleur anéantissant tout sur leur passage.', name_it = 'Fucile picca Ajara', description_it = 'Lancia-fucile Ajarakan che produce colpi di calore per rimuovere all''istante ogni cosa sul suo cammino.', name_es = 'Pica pistola Ajara', description_es = 'Lanza pistola de Ajarakan capaz de producir potentes explosiones de calor que eliminan al instante a cualquier obstáculo en su camino.' WHERE name_en = 'Ajara Gunpike' AND type = 'gunlance';
UPDATE equipment SET name_ja = 'レザー装備', description_ja = '皮をベースに軽い素材で作られた装備。 どんな状況にも柔軟に対応できる、基本を押さえた装備。', name_fr = 'Armure de cuir', description_fr = 'Armure faite de matériaux légers avec une base en cuir. Flexible en toute situation.', name_it = 'Armatura in cuoio', description_it = 'Armatura composta da inserti leggeri su una base in cuoio. La sua flessibilità la rende molto versatile.', name_es = 'Armadura cuero', description_es = 'Armadura elaborada con materiales ligeros y base de cuero. Brinda flexibilidad ante cualquier situación.' WHERE name_en = 'Leather Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ハンター装備', description_ja = '数多くのハンターが着用する代表的な装備。 頑丈な金属と柔軟な皮素材が使われている。', name_fr = 'Armure de Chasseur', description_fr = 'Armure universelle des chasseurs. Faite avec des métaux robustes et des peaux souples.', name_it = 'Arm. cacciatore', description_it = 'Armatura composta da metalli robusti e pelle flessibile, è indossata tipicamente dai cacciatori.', name_es = 'Armadura cazador', description_es = 'Armadura que los cazadores llevan por doquier, fabricada con materiales sólidos y una piel robusta a la vez que elástica.' WHERE name_en = 'Hunter Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ボーン装備', description_ja = '頑丈な骨をベースにした装備。 大胆に肌を露出したワイルドなデザインだが、防御力は十分。', name_fr = 'Armure d''os', description_fr = 'Armure faite d''os durs. Pourvue d''une défense élevée malgré ses choix extravagants de conception.', name_it = 'Armatura in osso', description_it = 'Armatura in osso duro. Permette un alto livello di difesa malgrado lo stile sia aggressivo.', name_es = 'Armadura hueso', description_es = 'Armadura hecha de hueso duro. A pesar de su excéntrico diseño, cuenta con un gran poder defensivo.' WHERE name_en = 'Bone Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'アロイ装備', description_ja = '良質な鉱石から作られる装備。 余計な装飾がない合理的な設計で実用面に特化している。', name_fr = 'Armure en alliage', description_fr = 'Armure faite de minerais de grande qualité. Créée spécialement pour être fonctionnelle, sans ornements.', name_it = 'Armatura in lega', description_it = 'Armatura realizzata con minerali d''alta qualità. Progettata unicamente per essere funzionale. Senza fronzoli.', name_es = 'Armadura aleación', description_es = 'Armadura hecha de mineral de gran calidad. Diseñada para ser funcional, carece de complementos innecesarios.' WHERE name_en = 'Alloy Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'クルル装備', description_ja = 'クルルヤックの大きな飾り羽がオシャレ。 暑く乾燥した環境に適した作りになっている。', name_fr = 'Armure Kululu', description_fr = 'Armure idéale pour les milieux chauds et arides, ornée de grandes plumes de Kulu-Ya-Ku.', name_it = 'Armatura Kululu', description_it = 'Armatura ideale per i climi caldi e aridi, decorata con grandi piume di Kulu-Ya-Ku.', name_es = 'Armadura Kululu', description_es = 'Armadura ideada para resistir en ambientes áridos y calurosos. Está decorada con grandes plumas de Kulu-Ya-Ku.' WHERE name_en = 'Kululu Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'プケプケ装備', description_ja = '頭をすっぽりと覆う独特なフードがプケプケの妖しさを醸す。 草葉の生い茂る場所では身を隠しやすく行動しやすい。', name_fr = 'Armure Pukei-Pukei', description_fr = 'Armure faite de Pukei-Pukei qui donne une aura mystérieuse. Idéale pour les mouvements furtifs et les attaques surprises.', name_it = 'Armatura Pukei-Pukei', description_it = 'Armatura di Pukei-Pukei dall''aura misteriosa. Utile per muoversi rapidamente e braccare furtivamente la preda nell''erba alta.', name_es = 'Armadura Pukei-Pukei', description_es = 'Envuélvete en misterio con esta armadura de Pukei-Pukei. Ideal para camuflarte y sorprender rápidamente a tu presa.' WHERE name_en = 'Pukei-Pukei Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ボロス装備', description_ja = 'とにかく硬く。何よりも硬く。 それだけを追及して作られたボルボロスの装備。まるで要塞。', name_fr = 'Armure Barroth', description_fr = 'Dure. Très dure. Faite à partir d''un Barroth avec simplement la dureté à l''esprit. C''est une forteresse.', name_it = 'Armatura Barroth', description_it = 'Tosta. Tostissima. Fatta con le parti di un Barroth, il più tosto dei tosti. È una vera fortezza.', name_es = 'Armadura Barroth', description_es = 'Forjada con un Barroth obsesionado con la fortaleza. Su solidez es pétrea: es como llevar puesta una fortificación inexpugnable.' WHERE name_en = 'Barroth Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'カガチ装備', description_ja = '蒼白い鱗に純白の体毛がアクセントなトビカガチの装備。 帽子状の頭部は表情がよく見えることで人気。', name_fr = 'Armure Tobi-Kadachi', description_fr = 'Armure faite d''écailles bleu ciel et de pelage blanc de Tobi-Kadachi. Son casque ne bloque pas le champ de vision.', name_it = 'Armatura Kadachi', description_it = 'Armatura fatta con scaglie azzurre e pelo bianco di un Tobi-Kadachi. L''elmo garantisce un''ottima visione.', name_es = 'Armadura Kadachi', description_es = 'Armadura hecha con las cerúleas escamas y blanco pelaje del Tobi-Kadachi. Disfruta las vistas, ya que el casco no bloqueará tu visión.' WHERE name_en = 'Kadachi Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ジャナフ装備', description_ja = '至る所にアンジャナフの毛皮を使った装備。 この毛皮は火にとても強く、燃えにくい。', name_fr = 'Armure Anjanath', description_fr = 'Armure richement décorée avec de la fourrure d''Anjanath résistante au feu.', name_it = 'Armatura Anja', description_it = 'Armatura impreziosita dalla pelle ignifuga di un Anjanath.', name_es = 'Armadura Anja', description_es = 'Armadura profusamente decorada con piel de Anjanath. Resiste al fuego.' WHERE name_en = 'Anja Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ジャナール装備', description_ja = '雷顎竜の異名を持つ、アンジャナフ亜種の装備。 灰色を基調に縞模様が特徴的な姿は、まるで凍る地の雷神。', name_fr = 'Armure Anja tonnerre', description_fr = 'Armure Anjanath tonnerre avec des rayures distinctives sur fond gris, comme un éclair sur un désert de glace.', name_it = 'Arm. Anja tonante', description_it = 'Armatura di Anjanath tonante con esclusivo motivo a strisce su sfondo grigio, come fulmini su una gelida terra desolata.', name_es = 'Arm. Anja Fulgúreo', description_es = 'Armadura de Anjanath Fulgúreo que luce un original diseño a rayas sobre fondo gris, como relámpagos sobre un erial helado.' WHERE name_en = 'Fulgur Anja Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'レイア装備', description_ja = '「陸の女王」の名にふさわしいリオレイアの装備。 並の金属では傷もつかない鱗が全身を覆う。', name_fr = 'Armure Rathian', description_fr = 'Armure faite à partir de la reine de la terre, la Rathian. Ses écailles sont insensibles aux métaux ordinaires.', name_it = 'Armatura Rathian', description_it = 'Armatura con parti della Regina della Terra, una Rathian. È coperta di scaglie resistenti ai comuni metalli.', name_es = 'Armadura Rathian', description_es = 'Armadura de Rathian, la reina de la tierra. Está cubierta de escamas inmunes a los metales comunes.' WHERE name_en = 'Rathian Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'リオハート装備', description_ja = '舞い散る花びらのような桜色の装備。 モンスターも目を奪われるほどの美しさで主を彩る逸品。', name_fr = 'Armure Cœur Rathian', description_fr = 'Armure rappelant les fleurs tombant d''un cerisier. Sa beauté ensorcellera même les monstres.', name_it = 'Arm. cuore Rath', description_it = 'Armatura che ricorda i petali di ciliegio che cadono nella brezza. La sua bellezza strega perfino i mostri.', name_es = 'Arm. corazón Rath', description_es = 'Armadura que evoca los pétalos caídos de la flor del cerezo. Su belleza es capaz de embrujar hasta a los monstruos.' WHERE name_en = 'Rath Heart Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ウルムー装備', description_ja = '白くもこもこしたパオウルムーの外観を模した装備。 首を膨らませた姿を彷彿させる、丸い帽子はとってもラブリー！', name_fr = 'Armure Lumu', description_fr = 'Armure faite à l''image d''un Paolumu blanc, munie d''un adorable chapeau qui ressemble au monstre quand il est gonflé.', name_it = 'Armatura Lumu', description_it = 'Armatura ispirata al bianco e soffice Paolumu, corredata di un grazioso cappello che ricorda il mostro quando si gonfia.', name_es = 'Armadura Lumu', description_es = 'Armadura hecha a imagen del suave y blanco Paolumu. El adorable gorro imita el aspecto del Monstie cuando se infla.' WHERE name_en = 'Lumu Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ハイメタ装備', description_ja = '貴重な鉱石をふんだんに使用した装備。 傷つけることさえ難しい強度を誇る。', name_fr = 'Armure de métal supérieur', description_fr = 'Armure à base de minerai rare. Très difficile à endommager.', name_it = 'Arm. metallo sup.', description_it = 'Fatta con un minerale raro. È molto difficile da danneggiare.', name_es = 'Armadura metálica', description_es = 'Armadura compuesta de un raro mineral. Presume de una fortaleza difícil de mermar.' WHERE name_en = 'High Metal Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ギエナ装備', description_ja = '風漂竜の翼に覆われたかのようなレイギエナ装備。 孤独な戦士かと思わせる風貌。', name_fr = 'Armure Legiana', description_fr = 'Porter cette armure donne l''impression d''être enveloppé dans les ailes d''un Legiana. Donne un air de guerrier solitaire.', name_it = 'Armatura Legiana', description_it = 'Chi indossa questa armatura sembra avvolto dalle ali di Legiana. Ricorda un guerriero solitario.', name_es = 'Armadura Legiana', description_es = 'Con esta armadura, parecerá que te envuelven las alas de un Legiana. Genera una sensación como de guerrero solitario.' WHERE name_en = 'Legiana Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ガロン装備', description_ja = '返り血の如き朱を帯びたオドガロンの装備。 身に付けた者は血に飢え獲物を求め彷徨う。', name_fr = 'Armure Odogaron', description_fr = 'Armure Odogaron rouge sang. Pousse ceux qui la portent à une chasse furieuse en quête de proie.', name_it = 'Armatura Odogaron', description_it = 'Di colore scarlatto e fatta con parti di Odogaron. Chi la indossa viene travolto da un bisogno spasmodico di cacciare.', name_es = 'Armadura Odogaron', description_es = 'Armadura carmesí de Odogaron. Cualquiera que la lleve se verá presa del frenesí de la caza.' WHERE name_en = 'Odogaron Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'デスガロン装備', description_ja = 'オドガロン亜種の素材を使用した装備。 使用者の中に眠る残忍なる本性を目覚めさせるという。', name_fr = 'Armure du désastre', description_fr = 'Armure fabriquée à partir de parties d''Odogaron désastre. Éveille la soif de cruauté du porteur.', name_it = 'Armatura d''ebano', description_it = 'Fatta con parti di Odogaron d''ebano. Risveglia in chi la indossa la sua crudeltà sopita.', name_es = 'Armadura de ébano', description_es = 'Armadura hecha a partir de partes de Odogaron Ébano. Despierta una sed de crueldad en su portador.' WHERE name_en = 'Death Garon Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'レウス装備', description_ja = '空の王者リオレウスの装備。 この世のどんな炎で焼かれようと決して燃えることはないという。', name_fr = 'Armure Rathalos', description_fr = 'Armure du roi des cieux, le Rathalos. On dit qu''il n''existe pas de flamme capable d''altérer cette armure.', name_it = 'Armatura Rathalos', description_it = 'Armatura del Re dei Cieli, Rathalos. Si dice non esista al mondo una fiamma in grado di bruciarla.', name_es = 'Armadura Rathalos', description_es = 'Armadura de Rathalos, el señor de los cielos. Se dice que no hay llama que pueda calcinar esta armadura.' WHERE name_en = 'Rathalos Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'リオソウル装備', description_ja = '蒼き空の王、リオレウス亜種の力をつかさどる装備。 その姿を見た者に二度と夜明けは訪れない。', name_fr = 'Armure Âme Rathalos', description_fr = 'Armure contenant le pouvoir du Rathalos azur, roi du ciel bleu. Ceux qui l''ont vu ne reverront pas le soleil.', name_it = 'Arm. anima Rath', description_it = 'Armatura che contiene il potere del Rathalos azzurro, il Re dei Cieli blu. Chi l''ha vista in azione non è arrivato a raccontarlo.', name_es = 'Armad. alma Rath', description_es = 'Armadura que contiene el poder del Rathalos Celeste, señor del cielo azul. Quien la presencia no vuelve a ver el amanecer.' WHERE name_en = 'Rath Soul Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ディアブロ装備', description_ja = '砂漠の暴君ディアブロスの甲殻で守られた装備。 巨大な２本の角はモンスターを震え上がらせる。', name_fr = 'Armure Diablos', description_fr = 'Armure faite à partir d''une carapace de Diablos, le tyran du désert. Les monstres trembleront de peur à la vue de ses cornes.', name_it = 'Armatura Diablos', description_it = 'Armatura fatta con carapace di Diablos. Le grosse corna faranno tremare di paura i mostri.', name_es = 'Armadura Diablos', description_es = 'Armadura hecha con la coraza de un Diablos, el terror de las arenas. Los monstruos temblarán al atisbar sus cuernos.' WHERE name_en = 'Diablos Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ディアネロ装備', description_ja = 'ディアブロス亜種の素材を使った迫力満点の装備。 黒くそびえるその姿は見る者を震え上がらせる。', name_fr = 'Armure Diablos noire', description_fr = 'Armure sans rivale faite à partir d''une Diablos noire. Ceux qui regardent sa forme imposante sont terrifiés.', name_it = 'Armatura Diablos nera', description_it = 'Armatura senza pari di Diablos nera. Chiunque ne veda la sagoma minacciosa trema di terrore.', name_es = 'Armadura Diablos Negra', description_es = 'Incomparable armadura hecha a partir de una Diablos Negra. Sembrará pavor en quien ose contemplar su imponente silueta.' WHERE name_en = 'Diablos Nero Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ダマスク装備', description_ja = '持ち主を覇道へ導くと伝えられる鋼鉄の甲冑。 長寿の竜人族でさえ生涯目にすることが少ない幻の防具。', name_fr = 'Armure Damascus', description_fr = 'Armure en acier qui conduit à la gloire. Objet d''une rareté exceptionnelle.', name_it = 'Armatura di Damasco', description_it = 'Armatura d''acciaio che si vede raramente nella vita. Si dice che porti alla gloria chi la indossa.', name_es = 'Armadura de Damasco', description_es = 'Pieza de armadura de acero que, según dicen, conduce a la gloria. Muy rara de ver.' WHERE name_en = 'Damascus Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'バンギス装備', description_ja = 'まるで生きているかのように脈動するイビルジョー素材の装備。 分厚くて頑丈な鱗で覆われている。', name_fr = 'Armure Vangis', description_fr = 'Faite avec les parties encore palpitantes d''un Deviljho. Couverte d''épaisses et robustes écailles.', name_it = 'Armatura Vangis', description_it = 'Composta di parti ancora palpitanti di Deviljho, è ricoperta di scaglie spesse e forti.', name_es = 'Armadura Vangis', description_es = 'Hecha con materiales aún latentes extraídos del Deviljho, está recubierta de duras y gruesas escamas.' WHERE name_en = 'Vangis Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ナルガ装備', description_ja = '夜の闇から生まれたかのような、ナルガクルガの装備。 漆黒の衣は影に溶けこみ、その存在を隠す。', name_fr = 'Armure Nargacuga', description_fr = 'Armure se fondant dans les ténèbres, faite à partir d''un Nargacuga. Cache son porteur.', name_it = 'Arm. Nargacuga', description_it = 'Armatura con parti di Nargacuga nato nell''oscurità della notte. Il tessuto scuro si fonde con l''ombra e cela chi la indossa.', name_es = 'Armad. Nargacuga', description_es = 'Armadura de Nargacuga engendrada en la negrura de la medianoche. Su oscuro tejido oculta a quien la lleve en las sombras.' WHERE name_en = 'Nargacuga Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ナルガＵ装備', description_ja = '深い森から生まれ落ちたようなナルガクルガ亜種の装備。 草木に紛れ、物音も立てず獲物に近付く。', name_fr = 'Armure Nargacuga U', description_fr = 'Armure faite à partir d''un Nargacuga opale, né dans les profondeurs de la forêt. Son porteur est camouflé.', name_it = 'Arm. Nargacuga U', description_it = 'Armatura fatta di Nargacuga verde. Si fonde con la foresta mentre chi la indossa bracca silenziosamente la preda.', name_es = 'Arm. Nargacuga U', description_es = 'Armadura de Nargacuga Verde forjada en el corazón del bosque. Se funde con el entorno a medida que la presa se va aproximando.' WHERE name_en = 'Nargacuga U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ディノ装備', description_ja = 'ディノバルドの炎状殻をそのまま身に着けたような装備。 戦う意思を捨てると、魂ごと斬り裂かれるという…。', name_fr = 'Armure Glavenus', description_fr = 'Armure faite à partir de la peau ardente d''un Glavenus qui n''aidera que ceux qui ont l''esprit combatif.', name_it = 'Armatura Glavenus', description_it = 'Armatura fatta di pelle ricavata dal dorso di un Glavenus. Attenzione, è adatta solo a chi ha un grande spirito combattivo.', name_es = 'Armadura Glavenus', description_es = 'Engalánate con el ígneo lomo de un Glavenus. Pero ojo: esta armadura solo favorece a un espíritu luchador.' WHERE name_en = 'Glavenus Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ブラキ装備', description_ja = 'ブラキディオスの強大なパワーが 込められた装備。爆発の衝撃にもびくともしない強度を持つ。', name_fr = 'Armure Brachydios', description_fr = 'Armure contenant l''énorme pouvoir d''un Brachydios. Elle est capable de résister à des explosions.', name_it = 'Arm. Brachydios', description_it = 'Armatura che contiene l''enorme potere di un Brachydios. È così dura da resistere alle esplosioni.', name_es = 'Armad. Brachydios', description_es = 'Armadura que alberga el inconmensurable poder de un Brachydios. Es tan poderosa que resiste las explosiones.' WHERE name_en = 'Brachydios Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'レックス装備', description_ja = 'ティガレックスの素材を使った装備。 思うがまま破壊を振りまく絶対強者を征した証。', name_fr = 'Armure Tigrex', description_fr = 'Armure faite à partir d''un Tigrex. Un symbole de pouvoir absolu et de destruction gratuite.', name_it = 'Armatura Tigrex', description_it = 'Armatura fatta con parti di Tigrex. Simbolo di potere assoluto. Simbolo di distruzione sfrenata.', name_es = 'Armadura Tigrex', description_es = 'Armadura hecha a partir del Tigrex. Es símbolo de poder absoluto y de desolación.' WHERE name_en = 'Tigrex Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'レックスＵ装備', description_ja = 'ティガレックス亜種の素材を用いた装備。 黒みを増した甲殻に絶対強者の記憶が刻まれている。', name_fr = 'Armure Tigrex U', description_fr = 'Armure faite à partir d''un Tigrex berserk. Sa carapace noire est empreinte de souvenirs de pouvoir absolu.', name_it = 'Armatura Tigrex U', description_it = 'Armatura fatta con parti di Tigrex nero. Memorie di potere assoluto sono ancora impresse nell’oscuro carapace.', name_es = 'Armadura Tigrex U', description_es = 'Armadura hecha a partir del Tigrex Pardo. El recuerdo de un poder absoluto está grabado en su oscura coraza.' WHERE name_en = 'Tigrex U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ラヴィーナ装備', description_ja = '華美な装飾が施された冰龍、イヴェルカーナの装備。 棘々しくも、寒色で統一し、目元を隠したデザインが美しい。', name_fr = 'Armure Velkhana', description_fr = 'Une superbe armure hérissée de pics de glace faite à partir d''un Velkhana, elle dissimule les yeux du porteur.', name_it = 'Armatura Velkhana', description_it = 'Stupenda armatura di Velkhana con aculei di ghiaccio. Nasconde gli occhi di chi l''indossa.', name_es = 'Armadura escarcha', description_es = 'Engalánate con témpanos espinosos vistiendo esta preciosa armadura de Velkhana que oculta los ojos de quien la lleva.' WHERE name_en = 'Rimeguard Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'テンタクル装備', description_ja = '深淵の闇を纏うが如きネロミェールの装備。 強き心を持たぬ者が身に付けると狂気に囚われるという。', name_fr = 'Armure Namielle', description_fr = 'Armure Namielle qui plonge son porteur dans les ténèbres. Seuls les cœurs résilients échappent à la folie de l''abysse.', name_it = 'Armatura Namielle', description_it = 'Armatura di Namielle che spinge chi la indossa sull''orlo della follia. Solo coloro che hanno una grande forza d''animo riescono a resistervi.', name_es = 'Armadura Namielle', description_es = 'Armadura de Namielle que sumerge al portador en la oscuridad. Solo aquellos de corazón recio pueden resistir la locura del abismo.' WHERE name_en = 'Tentacle Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ベリオ装備', description_ja = 'ベリオロスの素材で作られた装備。 雪のように白く、冷たい甲殻には、凍土の騎士の闘志が宿る。', name_fr = 'Armure Barioth', description_fr = 'Armure faite à partir d''un Barioth. L''esprit combatif des étendues glacées repose dans sa carapace.', name_it = 'Armatura Barioth', description_it = 'Armatura con parti di Barioth. Lo spirito combattivo di valli gelide è infuso nel carapace bianco neve.', name_es = 'Armadura Barioth', description_es = 'Armadura hecha con un Barioth. Su coraza nívea cobija el espíritu luchador de las gélidas tierras yermas.' WHERE name_en = 'Barioth Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ベリオＵ装備', description_ja = 'ベリオロス亜種の赤銅色の素材を使った装備。 砂漠に吹き荒れる熱砂の竜巻を思い起こさせる。', name_fr = 'Armure Barioth U', description_fr = 'Armure faite à partir de la peau tannée d''un Barioth des sables. Rappelle le sable brûlant du désert.', name_it = 'Arm. Barioth U', description_it = 'Armatura in pelle ambrata tipica del Barioth delle sabbie. Ricorda le sabbie ardenti del deserto.', name_es = 'Armad. Barioth U', description_es = 'Armadura forjada con la piel tostada de un Barioth Arenoso. Evoca los tornados de arena tórrida que campan por el desierto.' WHERE name_en = 'Barioth U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'アーティア装備', description_ja = '職人達を騒然とさせた謎の発掘品。 その未知の金属は強固な装備として現代に蘇った。', name_fr = 'Armure Artian', description_fr = 'Armure rigide faite dans un métal inconnu qui a médusé les artisans lorsqu''il fut découvert.', name_it = 'Armatura Artian', description_it = 'Protezione rigida di metallo sconosciuto che ha stupito i fabbri quando è stata scoperta.', name_es = 'Armadura artiana', description_es = 'Armadura rígida, hecha con un metal que asombra a los artesanos.' WHERE name_en = 'Artian Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ジンオウ装備', description_ja = '「無双の狩人」と呼ばれるジンオウガ。 並び立つ者のないその力を匠の技で封じ込めた装備。', name_fr = 'Armure Zinogre', description_fr = 'Armure faite en utilisant des matériaux d''un Zinogre. Son pouvoir sans égal y est scellé.', name_it = 'Armatura Zinogre', description_it = 'Armatura con parti di Zinogre. Al suo interno è stato abilmente racchiuso un potere incomparabile.', name_es = 'Armadura Zinogre', description_es = 'Armadura forjada con elementos de Zinogre. En su interior se ha encerrado con extrema pericia un poder sin igual.' WHERE name_en = 'Zinogre Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ジンオウＵ装備', description_ja = '龍の気を秘めたジンオウガ亜種の素材を使った装備。 モンスターも怯えるほどの迫力を兼ね備える。', name_fr = 'Armure Zinogre U', description_fr = 'Armure faite à partir d''un Zinogre stygien. Ses pouvoirs draconiens feront trembler les monstres.', name_it = 'Arm. Zinogre U', description_it = 'Armatura fatta con parti di Zinogre stigeo. Il suo potere draconico farà tremare anche i mostri.', name_es = 'Armad. Zinogre U', description_es = 'Armadura hecha con un Zinogre Estigio que contiene el ignoto poder de los dragones. Hará temblar a las mismísimas bestias.' WHERE name_en = 'Zinogre U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ガルルガ装備', description_ja = 'イャンガルルガから放たれる禍々しい気を封じ込めた装備。 傷つく度、より強固に再生する。', name_fr = 'Armure Garuga', description_fr = 'Armure faite en utilisant le pouvoir sinistre du Yian Garuga. Se renforce avec chaque coup reçu.', name_it = 'Armatura Garuga', description_it = 'Armatura creata utilizzando il sinistro potere di uno Yian Garuga. Si rinforza dopo ogni colpo ricevuto.', name_es = 'Armadura Garuga', description_es = 'Armadura forjada con el siniestro poder del Yian Garuga. Se vuelve más fuerte con cada golpe.' WHERE name_en = 'Garuga Armor' AND type = 'armor';
UPDATE equipment SET name_ja = '禍鎧装備', description_ja = '怨念を顕現したかの如きマガイマガドの装備。 鎧に宿りし禍の渦は身に付けた者をも貪り喰らう。', name_fr = 'Armure sinistre', description_fr = 'Armure débordant de la malveillance du Magnamalo. Le mal qui l''habite consume tout, même son porteur.', name_it = 'Armatura sinistra', description_it = 'Armatura permeata della malvagità di un Magnamalo. Il suo diabolico spirito divora tutto e tutti, incluso chi la indossa.', name_es = 'Armadura siniestra', description_es = 'Armadura rebosante de la malicia de un Magnamalo. La maldad del interior devora incluso a su portador.' WHERE name_en = 'Sinister Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'テンゴ装備', description_ja = '修行者の服を模したビシュテンゴの装備。 身に付けた者を導き、穢れから守ると伝えられている。', name_fr = 'Armure Bishaten', description_fr = 'Armure Bishaten modelée sur l''habit d''ascètes. On raconte qu''elle guiderait son porteur à l''écart du danger.', name_it = 'Armatura Bishaten', description_it = 'Fatta con parti di Bishaten modellate per richiamare le vesti degli asceti. Si narra che tenga alla larga la sfortuna.', name_es = 'Armadura Bishaten', description_es = 'Armadura de Bishaten creada a imagen de la túnica de un anacoreta. Supuestamente guía a su portador hacia la fortuna.' WHERE name_en = 'Bishaten Armor' AND type = 'armor';
