UPDATE equipment SET name_ja = 'ガーディアン装備', description_ja = '街を守護する騎士に与えられる装備。 精緻を極めた加工は、高い防御力と機能性を実現した。', name_fr = 'Armure Gardien', description_fr = 'Armure offerte aux soldats dont le rôle est de protéger leur ville. Finement conçue, elle offre une défense et une mobilité excellentes.', name_it = 'Armatura del guardiano', description_it = 'Prodotto di grande maestria portato dai cavalieri che hanno giurato di proteggere la propria città. Fornisce mobilità e difesa eccelse.', name_es = 'Armadura de guardián', description_es = 'Armadura otorgada a aquellos caballeros que juran defender su ciudad. Creada con esmero para ofrecer una defensa y movilidad excelentes.' WHERE name_en = 'Guardian Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ユクモ装備', description_ja = '遙か東の温泉郷で愛用される装備。 動きやすさを重視した作りで、様々な用途に用いられる。', name_fr = 'Armure Yukumo', description_fr = 'Armure portée par un lointain peuple oriental. Conçue pour faciliter les mouvements, elle est utile dans bien des situations.', name_it = 'Armatura Yukumo', description_it = 'Indossata dalla popolazione di alcuni luoghi del profondo oriente. È incentrata sulla mobilità, il che la rende ottima in molte situazioni.', name_es = 'Armadura Yukumo', description_es = 'Armadura propia de las gentes de tierras del lejano este. Su enfoque en maniobrabilidad la hace útil en multitud de situaciones.' WHERE name_en = 'Yukumo Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'レンジャー装備', description_ja = 'どんな環境下でも活動しやすいレンジャー用の装備。 肩のマークはアズラルのレンジャーの証。', name_fr = 'Armure de Ranger', description_fr = 'Armure faite spécialement pour les Rangers dans le but d''être utile dans tout environnement. L''emblème représente l''allégeance à Azuria.', name_it = 'Armatura del ranger', description_it = 'Pensata per i ranger e adatta a ogni clima. Il suo emblema è prova che chi la indossa è fedele ad Azuria.', name_es = 'Armadura de montaraz', description_es = 'Armadura hecha específicamente para montaraces con la idea de ser funcional en cualquier entorno. El emblema rinde lealtad a Azuria.' WHERE name_en = 'Ranger Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ブランゴ装備', description_ja = '異国の神の如き威光を放つドドブランゴの装備。 東方の技術で作られた逸品は予想外の強度を誇る。', name_fr = 'Armure Blango', description_fr = 'Armure à la majesté divine composée de parties de Blangonga. Ce chef-d''œuvre d''artisanat oriental se targue d''une défense surprenante.', name_it = 'Armatura Blango', description_it = 'Maestosa armatura fatta con parti di Blangonga. Quest''opera d''arte della manifattura orientale gode di una difesa inaspettatamente alta.', name_es = 'Armadura Blango', description_es = 'Armadura majestuosamente confeccionada con partes de Blangonga. Esta obra maestra de artesanía oriental disfruta de una defensa sorprendente.' WHERE name_en = 'Blango Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ガノス装備', description_ja = '水竜の鱗が縫い込まれたガノトトスの装備。 身体に密着する独特なデザインのスーツは、見た目に反して頑丈。', name_fr = 'Armure Plesioth', description_fr = 'Des écailles de Plesioth ont été cousues sur cette armure près du corps. Elle est plus résistante qu''il n''y paraît.', name_it = 'Armatura Plesioth', description_it = 'Armatura aderente rinforzata con scaglie di Plesioth. È più resistente di quanto sembri.', name_es = 'Armadura Plesioth', description_es = 'Armadura de corte entallado que está confeccionada con escamas de Plesioth. Es más recia de lo que parece.' WHERE name_en = 'Plesioth Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ガノスＵ装備', description_ja = '翠水竜の鱗に全身を覆われたガノトトス亜種の装備。 急所を的確にカバーしたその風貌にオトモンさえも怖気づく。', name_fr = 'Armure Plesioth U', description_fr = 'Armure en écailles de Plesioth vert. Elle a l''air tellement impénétrable qu''elle met même les Monsties mal à l''aise.', name_it = 'Armatura Plesioth U', description_it = 'Armatura con scaglie di Plesioth verde. È così intimidatoria da spaventare persino i Monstie.', name_es = 'Armadura Plesioth U', description_es = 'Armadura hecha con escamas de Plesioth Verde. Su aspecto intimidatorio e inquebrantable turba incluso a los Monsties.' WHERE name_en = 'Plesioth U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'クック装備', description_ja = 'イャンクックの素材で作られた色鮮やかな装備。 鋭くとがったトゲつきの甲殻は非常に頑丈。', name_fr = 'Armure Kut-Ku', description_fr = 'Armure aux couleurs vives faite à partir d''un Yian Kut-Ku. Sa carapace pointue lui confère une finition solide et de qualité.', name_it = 'Armatura Kut-Ku', description_it = 'Armatura dai colori vivaci fatta di parti di Yian Kut-Ku. Il carapace appuntito la rende molto robusta.', name_es = 'Armadura Kut-Ku', description_es = 'Armadura de vivos colores hecha a partir del Yian Kut-Ku. La coraza con afiladas púas le concede un acabado robusto.' WHERE name_en = 'Kut-Ku Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'クックＵ装備', description_ja = 'イャンクック亜種の良質な素材で作られた装備。 その独特の色味は歴戦を勝ち抜いてきた者の証。', name_fr = 'Armure Kut-Ku U', description_fr = 'Armure faite à partir d''un Yian Kut-Ku bleu. La couleur de l''armure est la preuve de nombreuses victoires.', name_it = 'Arm. Kut-Ku U', description_it = 'Armatura con parti di Yian Kut-Ku blu. Il colore peculiare è prova delle sue vittorie in una vita di battaglie.', name_es = 'Armad. Kut-Ku U', description_es = 'Armadura hecha a partir del Yian Kut-Ku Azul. Su singular tonalidad es prueba de sus victorias en una vida de batallas.' WHERE name_en = 'Kut-Ku U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ゲリョス装備', description_ja = 'ゲリョス特有のゴム質の皮を使用した装備。 弾力のある素材が高い防御力を生み出している。', name_fr = 'Armure Gypceros', description_fr = 'Armure faite en peau souple de Gypceros. La souplesse des matériaux permet une défense élevée.', name_it = 'Arm. Gypceros', description_it = 'Armatura fatta con la pelle elastica del Gypceros. I materiali flessibili permettono una difesa migliore.', name_es = 'Armad. Gypceros', description_es = 'Armadura elaborada con el versátil pellejo de un Gypceros. La elasticidad de los materiales proporciona una defensa férrea.' WHERE name_en = 'Gypceros Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ゲリョスＵ装備', description_ja = 'ゲリョス亜種の皮で覆われた、紫色の装備。 ぶ厚いゴム質の皮があらゆる攻撃を弾きかえす。', name_fr = 'Armure Gypceros U', description_fr = 'Armure faite à partir d''un Gypceros améthyste. L''épaisse peau souple repousse toutes les attaques.', name_it = 'Arm. Gypceros U', description_it = 'Armatura fatta con la pelle di un Gypceros viola. La pelle spessa ed elastica può respingere qualsiasi attacco.', name_es = 'Arm. Gypceros U', description_es = 'Armadura confeccionada con el pellejo de un Gypceros Morado: una piel gruesa y elástica que repele todos los ataques.' WHERE name_en = 'Gypceros U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'スキュラ装備', description_ja = 'ネルスキュラの素材で作られた装備。 高い防御力は、計算された設計と、確かな技術によるもの。', name_fr = 'Armure Nerscylla', description_fr = 'Armure faite à partir d''une Nerscylla. Sa conception précise et habile permet de fortes propriétés défensives.', name_it = 'Armatura Nerscylla', description_it = 'Armatura con parti di Nerscylla. Lo stile deciso e il disegno preciso permettono una difesa d''alto livello.', name_es = 'Armad. Nerscylla', description_es = 'Armadura hecha a partir del Nerscylla. Su minucioso diseño y buena factura le confieren sólidas propiedades defensivas.' WHERE name_en = 'Nerscylla Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'スキュラＵ装備', description_ja = 'ネルスキュラ亜種の素材を用いた装備。 夕暮の闇を思わせる色が、獲物を妖しげに誘っている。', name_fr = 'Armure Nerscylla U', description_fr = 'Armure faite à partir d''une Nerscylla spectrale. Attire sa proie dans son obscurité crépusculaire.', name_it = 'Arm. Nerscylla U', description_it = 'Armatura di Nerscylla ombroso che attrae le prede nella propria ammaliante oscurità crepuscolare.', name_es = 'Arm. Nerscylla U', description_es = 'Armadura hecha a partir del Nerscylla Sombrío. Su oscura belleza crepuscular es un reclamo para las presas.' WHERE name_en = 'Nerscylla U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ラギア装備', description_ja = '大海原の主であるラギアクルスの装備。 深海を思わせる深い蒼色は、静かに闘志をかきたてる。', name_fr = 'Armure Lagiacrus', description_fr = 'Armure faite à partir du seigneur des mers, le Lagiacrus. Son bleu profond rend peu à peu combatif.', name_it = 'Arm. Lagiacrus', description_it = 'Armatura con parti di Lagiacrus, Re dei Mari. Il suo blu profondo rende sempre più combattivo chi la indossa.', name_es = 'Armad. Lagiacrus', description_es = 'Armadura de Lagiacrus, señor de los mares. Su color azul como las profundidades marinas despertará las ansias de combatir.' WHERE name_en = 'Lagiacrus Armor' AND type = 'armor';
