UPDATE equipment SET name_ja = 'グラビド装備', description_ja = '溶岩にも耐えるグラビモスの、鎧のような甲殻で作られた装備。 大地がヒビ割れるほどの重量感。', name_fr = 'Armure Gravios', description_fr = 'Armure faite à partir de la carapace d''un Gravios, capable de résister à la lave. Assez lourde pour fendre la terre.', name_it = 'Armatura Gravios', description_it = 'Armatura fatta con carapace di Gravios. Resiste alla lava e pesa tanto da spaccare il terreno.', name_es = 'Armadura Gravios', description_es = 'Armadura de coraza de Gravios que resiste a la lava. Tan pesada que puede resquebrajar los cimientos de la tierra.' WHERE name_en = 'Gravios Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'グラビドＵ装備', description_ja = 'より黒く、より硬く成長したグラビモス亜種の装備。 空気すら重く感じるほどの威圧感。', name_fr = 'Armure Gravios U', description_fr = 'Armure faite à partir du rude et sombre Gravios onyx. Si intimidante que l''air même semblera lourd.', name_it = 'Arm. Gravios U', description_it = 'Armatura fatta con Gravios nero, più forte e scuro. Tanto minacciosa da rendere l''aria pesante.', name_es = 'Armad. Gravios U', description_es = 'Armadura forjada de un Gravios Negro, una versión más dura de roer y oscura. Tan sobrecogedora que coagula la tensión en el aire.' WHERE name_en = 'Gravios U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'ボロスＵ装備', description_ja = 'ボルボロス亜種の素材で作った装備。 巨大な氷塊を思わせる装甲は、ヒビ一つ入らない頑丈さ。', name_fr = 'Armure Barroth U', description_fr = 'Armure faite à partir d''un Barroth de jade. Sa vaste carapace en forme d''iceberg est très robuste.', name_it = 'Arm. Barroth U', description_it = 'Armatura con parti di un Barroth giada il cui enorme carapace, simile a un iceberg, è davvero resistentissimo.', name_es = 'Armad. Barroth U', description_es = 'Amadura hecha de un Barroth Esmeralda. Su inmenso caparazón con forma de iceberg le proporciona una solidez sin parangón.' WHERE name_en = 'Barroth U Armor' AND type = 'armor';
UPDATE equipment SET name_ja = 'シュバルカ装備', description_ja = 'アルシュベルドの素材で作られた装備。 かつて世界を震撼させた亡国の騎士の姿を模している。', name_fr = 'Armure Arkvulcan', description_fr = 'Armure faite de parties d''Arkveld. Similaire à celle que portait un chevalier sans royaume dont ont dit qu''il a changé la face du monde.', name_it = 'Armatura Arkvulcan', description_it = 'Armatura ricavata da resti di Arkveld. Fu indossata da un cavaliere rimasto senza patria che cambiò del tutto le sorti del mondo.', name_es = 'Armadura Arkvulcan', description_es = 'Armadura hecha con partes de Arkveld. Presenta el mismo diseño de un caballero sin reino que remodeló el mundo.' WHERE name_en = 'Arkvulcan Armor' AND type = 'armor';
